insert into public.tasks (course_id, day_number, title, book_insight, book_reference, instructions, response_prompt, min_response_chars, is_sample, resources) values
  ('3dd35700-943e-5264-ad06-a44982ca9cc3', 1, 'Write down your real number', 'How we handle money has less to do with what we know and more to do with how we behave — and behaviour starts with seeing clearly. Most people carry a vague feeling about their finances instead of an actual number. A feeling can''t be improved; a number can.', 'The Psychology of Money — Morgan Housel', '["Open every account you have: chequing, savings, credit cards, loans.","Add up what you own in cash and savings. Add up what you owe.","Subtract what you owe from what you own. That is today''s number.","Don''t judge it. Today is only about looking."]'::jsonb, 'What did it feel like to see your real number? What surprised you most? (You don''t have to share the number itself.)', 0, true, '[]'::jsonb),
  ('3dd35700-943e-5264-ad06-a44982ca9cc3', 2, 'Track every dollar for one day', 'A conscious spending plan begins with knowing what you spend now, not what you imagine you spend. Small, automatic purchases are the ones we forget, and they add up quietly. One honest day of tracking shows you more than a month of guessing.', 'I Will Teach You to Be Rich — Ramit Sethi', '["From the moment you read this, write down every purchase today — even a coffee.","Use your phone notes. Amount and what it was. Nothing else.","Tonight, mark each one: needed it, loved it, or didn''t notice it."]'::jsonb, 'What did you spend money on today, and which purchase would you not miss if it disappeared?', 0, true, '[]'::jsonb),
  ('3dd35700-943e-5264-ad06-a44982ca9cc3', 3, 'Pay yourself first — even $5', 'One of the oldest money rules is to keep a part of everything you earn before you spend the rest. The amount matters less than the order: saving first makes it a habit, saving what''s left makes it an accident. Wealth is mostly what you don''t spend.', 'The Richest Man in Babylon — George S. Clason (the first cure: start thy purse to fattening)', '["Pick an amount you will not miss. $5 is enough to start.","Move it into a savings account right now.","If your bank allows it, set this up as an automatic transfer on payday."]'::jsonb, 'How much did you move, and what will you set as your automatic ''pay yourself first'' amount?', 0, true, '[]'::jsonb),
  ('3dd35700-943e-5264-ad06-a44982ca9cc3', 4, 'Work out your real hourly wage', 'Money is something you trade your life energy for: every purchase costs hours of your life, not just dollars. Your true hourly wage is lower than the number on your contract once you subtract the time and money the job itself costs you. Knowing that number changes how expensive things look.', 'Your Money or Your Life — Vicki Robin & Joe Dominguez', '["Write down your take-home pay for a normal week.","Add the hours the job really takes: commuting, getting ready, unwinding afterwards, overtime.","Subtract what the job costs you each week: transport, work clothes, lunches bought, childcare.","Divide what is left by the real hours. That is your real hourly wage.","Take one recent purchase and convert it into hours of your life."]'::jsonb, 'What is your real hourly wage, and how many hours of your life did that one purchase cost?', 0, false, '[]'::jsonb),
  ('3dd35700-943e-5264-ad06-a44982ca9cc3', 5, 'List every recurring charge', 'Subscriptions are designed to be forgotten: a small monthly amount that renews without asking. Seeing them all in one list, with their yearly cost, turns a dozen invisible leaks into one visible number. You can only choose what to keep once you can see everything.', 'I Will Teach You to Be Rich — Ramit Sethi', '["Open your last two months of bank and card statements.","List every charge that repeats: streaming, apps, memberships, storage, software, insurance.","Next to each, write the yearly cost (monthly amount × 12).","Mark each one: use it weekly, use it sometimes, forgot I had it.","Add up the total. Don''t cancel anything yet — that is Day 12."]'::jsonb, 'How many recurring charges did you find, and what do they add up to per year?', 0, false, '[]'::jsonb),
  ('3dd35700-943e-5264-ad06-a44982ca9cc3', 6, 'Sort last month into four buckets', 'A spending plan does not need dozens of categories. Four are enough: fixed costs, investments, savings goals and guilt-free spending. Once you know the size of each bucket, you can stop feeling guilty about every purchase and start managing the proportions.', 'I Will Teach You to Be Rich — Ramit Sethi (the Conscious Spending Plan)', '["Take last month''s spending from your statements.","Put every item into one of four buckets: FIXED COSTS (rent, bills, groceries, debt payments), INVESTMENTS, SAVINGS, GUILT-FREE SPENDING (eating out, fun, shopping).","Work out each bucket as a percentage of your take-home pay.","Compare with the rough guide: fixed costs 50–60%, investments 10%, savings 5–10%, guilt-free 20–35%."]'::jsonb, 'What are your four percentages, and which bucket is furthest from where you want it?', 0, false, '[]'::jsonb),
  ('3dd35700-943e-5264-ad06-a44982ca9cc3', 7, 'Find the story behind your money habits', 'Nobody is crazy with money: people make decisions that make sense given what they lived through. The economy you grew up in and what your family did with money shaped your instincts long before you earned anything. Naming that story is the first step to deciding whether it still serves you.', 'The Psychology of Money — Morgan Housel (No One''s Crazy)', '["Write down your earliest memory involving money.","Finish three sentences: “In my family, money was…”, “Rich people are…”, “Spending on myself feels…”.","Circle one belief that is helping you and one that is costing you.","Rewrite the costly belief as a sentence you would rather live by."]'::jsonb, 'Which money belief did you inherit, and what sentence did you replace it with?', 0, false, '[]'::jsonb),
  ('3dd35700-943e-5264-ad06-a44982ca9cc3', 8, 'Define what ''enough'' means for you', 'The hardest financial skill is getting the goalpost to stop moving. Without a definition of enough, every raise is absorbed by a new want and comparison never ends. Past a certain point, more spending adds very little to how fulfilled you feel — knowing where that point is makes you free.', 'The Psychology of Money — Morgan Housel (Never Enough) · Your Money or Your Life — Vicki Robin & Joe Dominguez', '["List the five things you spend on that genuinely make your life better.","List three things you bought mainly because others have them.","Write a monthly number that would cover a life you would be content with.","Write one sentence starting: “For me, enough is…”"]'::jsonb, 'How did you finish the sentence “For me, enough is…”?', 0, false, '[]'::jsonb),
  ('3dd35700-943e-5264-ad06-a44982ca9cc3', 9, 'Sort what you own: asset or liability?', 'A simple test separates what builds wealth from what drains it: an asset puts money into your pocket, a liability takes money out. Many things people proudly call assets fail that test. The habit of asking which column something belongs in changes what you choose to buy.', 'Rich Dad Poor Dad — Robert T. Kiyosaki', '["Draw two columns: PUTS MONEY IN MY POCKET and TAKES MONEY OUT.","List the ten most valuable things you own or pay for, and place each one in a column.","For anything in the second column, write what it costs you each month.","Write one thing you could add to the first column in the next year, however small."]'::jsonb, 'What surprised you in the “takes money out” column, and what could you add to the other one?', 0, false, '[]'::jsonb),
  ('3dd35700-943e-5264-ad06-a44982ca9cc3', 10, 'Spot your ''look rich'' spending', 'Wealth is what you don''t see: it is the money that was not spent on the car, the clothes or the upgrade. Research on real millionaires found most of them live well below their means and look unremarkable. Spending to look rich is the fastest way to have less.', 'The Millionaire Next Door — Thomas J. Stanley & William D. Danko · The Psychology of Money — Morgan Housel (Wealth Is What You Don''t See)', '["Look back at the last three months of spending.","Mark anything bought mainly for how it looks to other people.","Add up those items.","Choose one of them you will not repeat, and decide where that money goes instead."]'::jsonb, 'What did your ''look rich'' spending add up to, and where will that money go now?', 0, false, '[]'::jsonb),
  ('3dd35700-943e-5264-ad06-a44982ca9cc3', 11, 'Choose your money dials', 'Being good with money is not about cutting everything. Spend extravagantly on the few things you love and cut costs mercilessly on the things you don''t. Deciding what your personal ''dials'' are makes saving feel like a choice instead of a punishment.', 'I Will Teach You to Be Rich — Ramit Sethi', '["Write the two or three things you would happily spend more on (travel, food, health, learning, convenience).","Write the five things you spend on but honestly do not care about.","Pick one from the second list and cut or downgrade it this week.","Decide which ''love'' category that freed money now belongs to."]'::jsonb, 'What are your money dials, and what did you cut to feed them?', 0, false, '[]'::jsonb),
  ('3dd35700-943e-5264-ad06-a44982ca9cc3', 12, 'Cancel one subscription you barely use', 'A subscription you rarely use still charges you every month for a version of yourself that does not exist. A better approach is to cancel and buy the thing only when you actually want it. You can always subscribe again — most people never do.', 'I Will Teach You to Be Rich — Ramit Sethi (the à la carte method)', '["Open your Day 5 list of recurring charges.","Pick the one marked “forgot I had it” or “use it sometimes”.","Cancel it now, while you are thinking about it. Screenshot the confirmation.","Work out what you will save in a year.","Set up a transfer of the same monthly amount into savings."]'::jsonb, 'Which subscription did you cancel, and how much will you save per year?', 0, false, '[]'::jsonb),
  ('3dd35700-943e-5264-ad06-a44982ca9cc3', 13, 'Ask for a lower bill or a waived fee', 'Companies expect most customers never to ask. A five-minute, polite call to request a lower rate or the removal of a fee works far more often than people assume, especially for long-standing customers. The worst answer you can get is no.', 'I Will Teach You to Be Rich — Ramit Sethi', '["Pick one bill: phone, internet, insurance, a bank fee, a credit-card interest rate.","Look up a competitor''s current price so you have a number to quote.","Call or use the chat and say: “I''ve been a customer for [X] years. I''ve seen [competitor] at [price]. What can you do to keep me?”","If the first person says no, ask politely to speak with the retention team.","Write down what you were offered, even if you did not take it."]'::jsonb, 'Which bill did you negotiate, and what happened when you asked?', 0, false, '[]'::jsonb),
  ('3dd35700-943e-5264-ad06-a44982ca9cc3', 14, 'Start a starter emergency fund', 'The first step out of money stress is a small cash buffer, built quickly. A modest starter fund means the next flat tyre or broken phone is an inconvenience instead of a new debt. It is not an investment — it is insurance against life.', 'The Total Money Makeover — Dave Ramsey (Baby Step 1)', '["Open a separate savings account, with no card attached, and name it “Emergency”.","Set a starter target you can reach within a few months. One month of bare essentials is a good first goal.","Move something into it today, even a small amount.","List three things you could sell or pause to reach the target faster."]'::jsonb, 'What is your starter target, and what did you move in today?', 0, false, '[]'::jsonb),
  ('3dd35700-943e-5264-ad06-a44982ca9cc3', 15, 'Line up your debts for a snowball', 'Paying off debt is more about behaviour than arithmetic. Listing debts from smallest to largest balance and attacking the smallest first gives you a quick win, and each debt you clear frees its payment for the next. Momentum keeps people going when maths alone does not.', 'The Total Money Makeover — Dave Ramsey (the debt snowball)', '["List every debt except a mortgage: balance, interest rate, minimum payment.","Order them from smallest balance to largest.","Commit to minimums on all of them, plus every spare dollar on the smallest.","Work out when the smallest one will be gone.","If you have no debt, list your next three savings goals in the same way."]'::jsonb, 'What is your smallest debt, and when will it be paid off at your new pace?', 0, false, '[]'::jsonb),
  ('3dd35700-943e-5264-ad06-a44982ca9cc3', 16, 'Try the 70–20–10 split', 'An old tale tells of a man deep in debt who climbed out by dividing every coin he earned: most to live on, a part kept for himself, and a part paid faithfully to those he owed. A fixed split takes the daily decision out of your hands. You stop asking what you can afford and simply follow the rule.', 'The Richest Man in Babylon — George S. Clason (the clay tablets from Babylon)', '["Take your monthly take-home pay.","Work out three numbers: 70% to live on, 10% to keep for yourself, 20% for debts (or extra savings if you have none).","Compare with what you actually do now.","Choose one change that moves you closer to the split this month."]'::jsonb, 'What are your three numbers, and what one change will you make this month?', 0, false, '[]'::jsonb),
  ('3dd35700-943e-5264-ad06-a44982ca9cc3', 17, 'Automate one transfer', 'Willpower is unreliable; a system is not. When money moves automatically on payday — to savings, investments and bills — the right thing happens whether or not you feel motivated. Building it once does more than a year of good intentions.', 'I Will Teach You to Be Rich — Ramit Sethi (automating your money)', '["Log in to your main bank account.","Set up a standing transfer for the day after payday.","Send it to savings, your emergency fund or a debt — whichever is your priority right now.","Start with an amount that feels almost too easy. You can raise it later."]'::jsonb, 'What transfer did you automate, for how much, and on which day does it run?', 0, false, '[]'::jsonb),
  ('3dd35700-943e-5264-ad06-a44982ca9cc3', 18, 'Separate needs from desires', 'What each of us calls ''necessary expenses'' always grows to match our income unless we push back. Everyone has more desires than their earnings can satisfy, so the skill is choosing which ones are worth the money. A budget is not a cage; it protects your most valued wishes from your passing ones.', 'The Richest Man in Babylon — George S. Clason (the second cure: control thy expenditures)', '["List everything you plan to spend on this coming week.","Mark each item N (truly necessary) or D (a desire).","Challenge every N: could you live a month without it?","Rank your D items and keep only those worth more to you than the saving."]'::jsonb, 'Which ''need'' turned out to be a desire, and which desire did you decide was worth keeping?', 0, false, '[]'::jsonb),
  ('3dd35700-943e-5264-ad06-a44982ca9cc3', 19, 'Use cash for one category', 'Handing over physical cash hurts in a way that tapping a card does not, and that small pain makes people spend less. Putting a fixed amount of cash in an envelope for one category means that when it is empty, you stop. It is a simple brake you can feel.', 'The Total Money Makeover — Dave Ramsey (the envelope system)', '["Pick the category you overspend on most: eating out, groceries or fun.","Decide a weekly limit for it.","Withdraw that amount in cash and put it in a labelled envelope.","Pay for that category with cash only for the next seven days."]'::jsonb, 'Which category did you choose, what limit did you set, and how did paying in cash feel?', 0, false, '[]'::jsonb),
  ('3dd35700-943e-5264-ad06-a44982ca9cc3', 20, 'Build in room for error', 'The most important part of every plan is planning for the plan not going to plan. A margin of safety — spare cash, lower fixed costs, conservative assumptions — lets you survive bad luck long enough for good luck to work. You don''t have to predict what goes wrong, only leave room for it.', 'The Psychology of Money — Morgan Housel (Room for Error)', '["Write the three money shocks most likely to hit you: job loss, a repair, illness, a rent increase.","For each one, write how many weeks you could cope today.","Choose the one that worries you most.","Take one action to widen the margin: add to your emergency fund, lower one fixed cost or review one insurance policy."]'::jsonb, 'Which shock worries you most, and what did you do today to leave more room for it?', 0, false, '[]'::jsonb),
  ('3dd35700-943e-5264-ad06-a44982ca9cc3', 21, 'Write your one-page spending plan', 'A plan you can keep on one page is a plan you will follow. Decide the percentages once, automate them, and you no longer need to track every coffee. The aim is to spend without guilt because the important things have already been taken care of.', 'I Will Teach You to Be Rich — Ramit Sethi (the Conscious Spending Plan)', '["Take your four buckets from Day 6.","Write a target percentage for each that you can realistically hit within three months.","Turn each percentage into a monthly dollar amount.","Next to each bucket, write how the money gets there: an automatic transfer, a separate account or cash.","Put the page where you will see it."]'::jsonb, 'What are your four target percentages, and which one will be hardest to hit?', 0, false, '[]'::jsonb),
  ('3dd35700-943e-5264-ad06-a44982ca9cc3', 22, 'See compounding with your own numbers', 'The most powerful force in money is not a high return; it is a decent return left alone for a very long time. Most of the growth arrives in the later years, which is why starting early and not interrupting it matters more than picking the perfect investment. Time is the ingredient nobody can buy back.', 'The Psychology of Money — Morgan Housel (Confounding Compounding)', '["Open any free online compound-interest calculator.","Enter an amount you could invest monthly and a moderate yearly return, for 10 years.","Run it again for 20, 30 and 40 years, changing nothing else.","Note how much of the final figure is growth, not your own deposits."]'::jsonb, 'What did your monthly amount grow to after 10 years and after 40 — and what does that tell you about waiting?', 0, false, '[]'::jsonb),
  ('3dd35700-943e-5264-ad06-a44982ca9cc3', 23, 'Learn what an index fund costs', 'For most people the simplest route works best: own a broad, low-cost index fund that holds the whole market, keep adding to it, and leave it alone. Fees look tiny as a percentage and are enormous over decades. Complexity usually benefits the person selling it.', 'The Simple Path to Wealth — JL Collins', '["Search for a broad market index fund available in your country.","Find its yearly fee (called the expense ratio or MER).","Compare it with the fee on any fund you already own, or a typical actively managed fund.","Work out what a 1% difference costs per year on $10,000.","This is learning, not advice — write down any questions for a licensed adviser."]'::jsonb, 'What fee did you find on the index fund, and how does it compare with what you pay now?', 0, false, '[]'::jsonb),
  ('3dd35700-943e-5264-ad06-a44982ca9cc3', 24, 'Claim any free money on offer', 'Before anything clever, take the guaranteed wins. If your employer matches retirement contributions, that match is an instant return you cannot get anywhere else. Leaving it unclaimed is turning down part of your salary.', 'I Will Teach You to Be Rich — Ramit Sethi (the ladder of personal finance)', '["Find out whether your employer offers a retirement match or any savings plan.","Check what you contribute now and how much of the match you receive.","If you are not getting the full match, write the exact step to change it (a form, a portal, an email to HR).","Do that step today, or book a time this week.","No employer plan? Look up the tax-advantaged account available in your country and write down its yearly limit."]'::jsonb, 'What free money or tax advantage is available to you, and what did you do about it today?', 0, false, '[]'::jsonb),
  ('3dd35700-943e-5264-ad06-a44982ca9cc3', 25, 'Put your savings to work', 'Money kept idle only buys what it buys today. The old lesson is that each coin saved should be put to labour, so that it earns more coins and those coins earn in turn. Wealth is not the pile you hold but the stream it produces.', 'The Richest Man in Babylon — George S. Clason (the third cure: make thy gold multiply)', '["Look at where your savings sit right now.","Find the interest rate each account pays.","Compare with one better option: a high-interest savings account, or the index fund from Day 23.","Decide how much of your savings beyond the emergency fund could work harder.","Write the next step, even if it is only “open an account”."]'::jsonb, 'How much is your money earning now, and what is your next step to make it earn more?', 0, false, '[]'::jsonb),
  ('3dd35700-943e-5264-ad06-a44982ca9cc3', 26, 'Check one ''opportunity'' for the catch', 'The first rule of investing is not to lose the principal. Promises of unusually high returns attract people precisely because they sound good, and the wise check with those who truly know before parting with money. If you cannot explain how it makes money, you are the product.', 'The Richest Man in Babylon — George S. Clason (the fourth cure: guard thy treasures from loss)', '["Think of one investment or scheme you have been pitched or tempted by.","Write the promised return and who benefits if you buy.","Answer three questions: How does it actually make money? What could make me lose all of it? Who with real experience have I asked?","If you cannot answer all three, write “not yet” beside it."]'::jsonb, 'What opportunity did you examine, and which of the three questions could you not answer?', 0, false, '[]'::jsonb),
  ('3dd35700-943e-5264-ad06-a44982ca9cc3', 27, 'Increase your ability to earn', 'There is a limit to how much you can cut, but not to how much you can learn to earn. The person who steadily improves their skill is paid more, and asking for a raise works best when you arrive with evidence. Your earning power is your largest asset.', 'The Richest Man in Babylon — George S. Clason (the seventh cure: increase thy ability to earn) · I Will Teach You to Be Rich — Ramit Sethi', '["Write down three results you delivered in the past year, with numbers where possible.","Look up what others in your role are paid.","Name one skill that would make you worth more within six months.","Take one step today: book a conversation with your manager, enrol in something, or start a side-income idea."]'::jsonb, 'What skill will raise your income, and what step did you take towards it today?', 0, false, '[]'::jsonb),
  ('3dd35700-943e-5264-ad06-a44982ca9cc3', 28, 'Plan to stay wealthy, not just get wealthy', 'Getting money and keeping money are different skills. Getting it takes optimism and risk; keeping it takes humility and a fear that what you made can be taken away. The investors who win are rarely the smartest — they are the ones who manage never to be wiped out.', 'The Psychology of Money — Morgan Housel (Getting Wealthy vs. Staying Wealthy)', '["Write the single financial mistake that could set you back five years.","List what you are doing now that makes it more likely: too much debt, one income, everything in one place.","Write one rule that protects you from it.","Tell someone you trust that rule, so they can hold you to it."]'::jsonb, 'What is your ''never get wiped out'' rule?', 0, false, '[]'::jsonb),
  ('3dd35700-943e-5264-ad06-a44982ca9cc3', 29, 'Protect your future income', 'A sensible person provides in advance for the years when they can no longer earn, and for the family that depends on them. Small, regular provision made early is far lighter than a large one attempted late. Protection is the unexciting half of wealth.', 'The Richest Man in Babylon — George S. Clason (the sixth cure: insure a future income)', '["List who depends on your income.","Check what protection you already have: insurance through work, life or disability cover, a pension.","Check that the beneficiaries named on your accounts and policies are correct.","Write down one gap, and the name of the person or company you will ask about it."]'::jsonb, 'What gap did you find in your protection, and who will you ask about it?', 0, false, '[]'::jsonb),
  ('3dd35700-943e-5264-ad06-a44982ca9cc3', 30, 'Decide what freedom looks like', 'The highest dividend money pays is control over your time: the ability to do what you want, when you want, with whom you want. Savings buy options, and options are a form of wealth that never shows on a statement. Knowing what you would do with that freedom tells you what you are saving for.', 'The Psychology of Money — Morgan Housel (Freedom) · The Simple Path to Wealth — JL Collins', '["Describe an ordinary weekday in a life where you control your time.","Estimate what that life would cost per month.","Work out how many months of that life your current savings would buy.","Write the number of months you want to reach, and by when."]'::jsonb, 'What does a free weekday look like for you, and how many months of it could you afford today?', 0, false, '[]'::jsonb),
  ('3dd35700-943e-5264-ad06-a44982ca9cc3', 31, 'Write your money rules', 'The best financial plan is not the one that is mathematically perfect; it is the one you can stick with when things get difficult. A few reasonable rules you actually follow beat an optimal strategy you abandon. You have spent a month building the pieces — now put them on one page.', 'The Psychology of Money — Morgan Housel (Reasonable > Rational)', '["Write five rules in your own words. For example: I pay myself first. I keep [X] months of expenses. I spend freely on [your dials]. I never buy an investment I cannot explain.","Look at your Day 1 number and work out today''s.","Put a 20-minute money check-in in your calendar, repeating monthly.","Choose the one habit from this course you will keep no matter what."]'::jsonb, 'What are your five money rules, and how has your number changed since Day 1?', 0, false, '[]'::jsonb),
  ('33721a9a-e30c-5b65-aa47-b904fe2bfd83', 1, 'Choose the person, not the goal', 'Lasting change comes from deciding who you want to be, then proving it to yourself with small wins. Every action is a vote for a type of person. You don''t need a perfect record — you need a majority of votes.', 'Atomic Habits — James Clear (identity-based habits)', '["Finish this sentence: ''I am the kind of person who…''","Pick ONE habit that person would do every day.","Make it small enough to do in two minutes.","Do it once today, right after you finish this task."]'::jsonb, 'Who are you becoming, and what is the two-minute habit you chose?', 0, true, '[]'::jsonb),
  ('33721a9a-e30c-5b65-aa47-b904fe2bfd83', 2, 'Find your cue', 'Every habit runs on a loop: a cue, a routine and a reward. Habits don''t stick because we want them to — they stick when something in the day reliably triggers them. Tie a new routine to a cue that already happens every day.', 'The Power of Habit — Charles Duhigg (the habit loop)', '["List three things you already do every single day (coffee, brushing teeth, opening your laptop).","Pick one as your cue.","Write your plan: ''After I [cue], I will [habit].''","Run it once today."]'::jsonb, 'What is your ''After I…, I will…'' sentence, and did you run it today?', 0, true, '[]'::jsonb),
  ('33721a9a-e30c-5b65-aa47-b904fe2bfd83', 3, 'Do it when you don''t feel like it', 'Most of us stop long before we are actually done — the mind asks to quit well before the body has to. Discipline grows in the moments you''d rather not, because those are the only moments that train it. Small voluntary discomfort makes the big ones easier.', 'Can''t Hurt Me — David Goggins', '["Pick the moment today when you least want to do your habit.","Do it then, on purpose.","Notice the excuse your mind offers. Write it down word for word."]'::jsonb, 'What excuse did your mind give you today, and what did you do anyway?', 0, true, '[]'::jsonb),
  ('33721a9a-e30c-5b65-aa47-b904fe2bfd83', 4, 'Shrink it to two minutes', 'A new habit should take less than two minutes to do. The point is not the two minutes; it is to master the art of showing up, because a habit has to be established before it can be improved. Make it so easy you cannot say no.', 'Atomic Habits — James Clear (the two-minute rule)', '["Write the full version of your habit (for example: run 5 km).","Write the two-minute version (put on running shoes and step outside).","Do only the two-minute version today. You are allowed to stop.","Decide that the two-minute version is what counts as ''done'' for now."]'::jsonb, 'What is the two-minute version of your habit, and did you stop there or keep going?', 0, false, '[]'::jsonb),
  ('33721a9a-e30c-5b65-aa47-b904fe2bfd83', 5, 'Celebrate the second you finish', 'Habits are wired in by emotion, not by repetition alone. Feeling good at the moment you do the behaviour tells your brain to do it again. A tiny, immediate celebration is how you create that feeling on purpose.', 'Tiny Habits — BJ Fogg (celebration)', '["Choose a celebration that feels natural: a fist pump, a smile, saying “Yes!” or “Done.”","Do your habit.","Celebrate within one second of finishing.","Repeat it three times today so the celebration itself becomes automatic."]'::jsonb, 'Which celebration did you choose, and how did it feel to do it straight after the habit?', 0, false, '[]'::jsonb),
  ('33721a9a-e30c-5b65-aa47-b904fe2bfd83', 6, 'Give it a time and a place', 'People who state exactly when and where they will act are far more likely to follow through. A vague intention leaves the decision for later, and later you will be tired. A specific plan means the moment itself tells you what to do.', 'Atomic Habits — James Clear (implementation intentions)', '["Complete this sentence: “I will [habit] at [time] in [place].”","Write it on paper and put it where you will see it.","Set an alarm for one minute before that time.","Do your habit today and tick it off."]'::jsonb, 'What is your exact time and place, and did you do the habit there today?', 0, false, '[]'::jsonb),
  ('33721a9a-e30c-5b65-aa47-b904fe2bfd83', 7, 'Score your daily habits', 'Most of what you do each day runs on autopilot, and you cannot change what you do not notice. Listing your routines and marking each one as helpful, harmful or neutral brings them into view. Awareness comes before any change.', 'Atomic Habits — James Clear (the habits scorecard)', '["Write everything you do from waking until you leave home, step by step.","Mark each one: + if it helps the person you want to be, – if it works against them, = if neutral.","Do the same for your evening.","Circle one minus you would most like to change.","Do your habit today and tick it off."]'::jsonb, 'What surprised you on your scorecard, and which minus did you circle?', 0, false, '[]'::jsonb),
  ('33721a9a-e30c-5b65-aa47-b904fe2bfd83', 8, 'Make the cue impossible to miss', 'Environment is the invisible hand that shapes behaviour. We do what is in front of us, so the most reliable way to start a habit is to make its cue obvious. Don''t rely on remembering — redesign the room.', 'Atomic Habits — James Clear (1st law: make it obvious)', '["Decide what object triggers your habit: the book, the shoes, the notebook, the water bottle.","Put it where you cannot avoid seeing it at the right moment.","Remove one thing from that spot that competes for your attention.","Do your habit today and tick it off."]'::jsonb, 'What did you change in your surroundings, and did it make starting easier?', 0, false, '[]'::jsonb),
  ('33721a9a-e30c-5b65-aa47-b904fe2bfd83', 9, 'Start a visible streak', 'Tracking a habit makes it obvious, attractive and satisfying all at once: the record reminds you to act, and seeing progress is its own reward. The simplest tracker is a calendar with a mark for each day done. The chain becomes something you don''t want to break.', 'Atomic Habits — James Clear (habit tracking)', '["Take a paper calendar or draw 66 boxes on a sheet.","Mark the days you have done so far.","Put it somewhere you see daily.","From now on, mark the box immediately after the habit.","Do your habit today and tick it off."]'::jsonb, 'Where did you put your tracker, and how many boxes are filled so far?', 0, false, '[]'::jsonb),
  ('33721a9a-e30c-5b65-aa47-b904fe2bfd83', 10, 'Make the ''never miss twice'' rule', 'Missing once is an accident. Missing twice is the start of a new habit. Perfection is not possible, so the people who succeed are not the ones who never slip but the ones who get back on track fastest.', 'Atomic Habits — James Clear (never miss twice)', '["Write the rule in your own words: “If I miss a day, I do it the next day, no matter what.”","Write your emergency version: the smallest possible form of the habit for terrible days.","Tell one person about the rule.","Do your habit today and tick it off."]'::jsonb, 'What is your emergency version for bad days, and who did you tell?', 0, false, '[]'::jsonb),
  ('33721a9a-e30c-5b65-aa47-b904fe2bfd83', 11, 'Find the reward you are really after', 'Cravings drive habits. To understand a routine you want to change or strengthen, experiment with the reward: what you think you are after is often not what actually satisfies you. Once you know the real craving, you can feed it deliberately.', 'The Power of Habit — Charles Duhigg (experiment with rewards)', '["Think about how you feel right after your habit.","Write the first three words that come to mind.","Ask: is it relief, pride, energy, calm, connection?","Name the reward in one word and write it beside your tracker.","Do your habit today and tick it off."]'::jsonb, 'What is the real reward your habit gives you, in one word?', 0, false, '[]'::jsonb),
  ('33721a9a-e30c-5b65-aa47-b904fe2bfd83', 12, 'Pair it with something you love', 'We are more likely to do something when it is attached to something we already enjoy. Allowing yourself a pleasure only while or after doing the habit makes the habit itself more attractive. It links what you need to do with what you want to do.', 'Atomic Habits — James Clear (2nd law: make it attractive — temptation bundling)', '["List three small pleasures: a podcast, good coffee, a favourite playlist, a show.","Pick one and make a rule: “I only [pleasure] while or right after I [habit].”","Try it today.","Do your habit today and tick it off."]'::jsonb, 'What did you bundle your habit with, and did it change how much you wanted to start?', 0, false, '[]'::jsonb),
  ('33721a9a-e30c-5b65-aa47-b904fe2bfd83', 13, 'Remove the friction', 'People drift towards whatever takes the least effort. Each extra step between you and a good habit makes it less likely to happen, so prepare the path in advance. Set things up so that doing it is the easy option.', 'Atomic Habits — James Clear (3rd law: make it easy)', '["Count the steps between you and starting your habit.","Remove at least one tonight: lay out the clothes, open the document, fill the bottle, charge the device.","Prepare tomorrow''s session before you go to bed.","Do your habit today and tick it off."]'::jsonb, 'Which step did you remove, and what did you prepare for tomorrow?', 0, false, '[]'::jsonb),
  ('33721a9a-e30c-5b65-aa47-b904fe2bfd83', 14, 'Face the accountability mirror', 'You cannot fix what you will not admit. Looking yourself in the eye and saying the unvarnished truth about where you are — and what you will do about it — is where change begins. Nobody else needs to hear it; you do.', 'Can''t Hurt Me — David Goggins (the accountability mirror)', '["Stand in front of a mirror tonight.","Say out loud one honest truth about where you have been letting yourself down.","Write it on a sticky note along with one action for tomorrow, and stick it on the mirror.","Tomorrow, do that action and replace the note.","Do your habit today and tick it off."]'::jsonb, 'What truth did you tell yourself in the mirror, and what action did you write on the note?', 0, false, '[]'::jsonb),
  ('33721a9a-e30c-5b65-aa47-b904fe2bfd83', 15, 'Make one bad habit invisible', 'Self-control is a short-term strategy. People who appear disciplined mostly arrange their lives so they are not tempted in the first place. To drop a bad habit, cut off the cue that starts it.', 'Atomic Habits — James Clear (inversion of the 1st law: make it invisible)', '["Take the minus you circled on Day 7.","Find its cue: a place, an app, a time, an object.","Remove or hide it today: delete the app, move the snacks, leave the phone in another room.","Do your habit today and tick it off."]'::jsonb, 'Which cue did you remove, and how often did you reach for it out of habit?', 0, false, '[]'::jsonb),
  ('33721a9a-e30c-5b65-aa47-b904fe2bfd83', 16, 'Slow your breath before you decide', 'Willpower is a state of the body as well as the mind. Slowing your breathing to four to six breaths a minute shifts the body out of stress mode and into a state where self-control is easier. A minute or two is enough to feel the difference.', 'The Willpower Instinct — Kelly McGonigal (the pause-and-plan response)', '["The next time you feel like skipping your habit or giving in to something, stop.","Breathe slowly for two minutes: about five seconds in, five seconds out.","Then decide.","Note what you chose after the pause.","Do your habit today and tick it off."]'::jsonb, 'When did you use the slow breath today, and what did you choose after it?', 0, false, '[]'::jsonb),
  ('33721a9a-e30c-5b65-aa47-b904fe2bfd83', 17, 'Protect tomorrow''s willpower tonight', 'When you are short on sleep, the part of the brain that handles self-control works less well, and stress and cravings win more easily. Rest is not a reward for being disciplined; it is the fuel for it. A consistent bedtime is a discipline habit in disguise.', 'The Willpower Instinct — Kelly McGonigal (sleep and self-control)', '["Decide on a bedtime that gives you at least seven hours.","Set an alarm 30 minutes before it to start winding down.","Keep it tonight.","Tomorrow, notice how hard or easy the habit feels.","Do your habit today and tick it off."]'::jsonb, 'What bedtime did you set, and did you keep it?', 0, false, '[]'::jsonb),
  ('33721a9a-e30c-5b65-aa47-b904fe2bfd83', 18, 'Find people for whom it is normal', 'We pick up habits from the people around us: those close to us, the wider group, and those we admire. The most effective thing you can do is join a group where the behaviour you want is the ordinary behaviour. Belonging does the work that willpower cannot.', 'Atomic Habits — James Clear (the role of family and friends)', '["Name one person or group for whom your habit is completely normal.","Make contact today: join the group, follow them, send a message, sign up for a class.","Tell them what you are doing.","Do your habit today and tick it off."]'::jsonb, 'Who did you connect with, and what did you tell them?', 0, false, '[]'::jsonb),
  ('33721a9a-e30c-5b65-aa47-b904fe2bfd83', 19, 'Notice what your habit is changing', 'Some habits matter more than others because they set off a chain of other changes. These keystone habits shift how people see themselves, and other good routines follow without being planned. Your one small habit is probably already touching other parts of your day.', 'The Power of Habit — Charles Duhigg (keystone habits)', '["Look back over the last 18 days.","List anything else that has changed since you started: sleep, mood, food, focus, how you talk to yourself.","Mark the changes you did not plan.","Do your habit today and tick it off."]'::jsonb, 'What else has started to change since you began, without you planning it?', 0, false, '[]'::jsonb),
  ('33721a9a-e30c-5b65-aa47-b904fe2bfd83', 20, 'Add the word ''yet''', 'If you believe your abilities are fixed, every difficulty is proof that you are not good enough. If you believe they can be developed, difficulty is simply what learning feels like. One small word — yet — turns a verdict into a direction.', 'Mindset — Carol S. Dweck', '["Listen today for any sentence where you say “I can''t” or “I''m not a … person”.","Write it down.","Add “yet” to the end and read it again.","Write the next small step that would move it forward.","Do your habit today and tick it off."]'::jsonb, 'Which “I can''t” did you turn into “not yet”, and what is the next small step?', 0, false, '[]'::jsonb),
  ('33721a9a-e30c-5b65-aa47-b904fe2bfd83', 21, 'See how small choices compound', 'Results come from small, smart choices repeated consistently over time. Each one looks insignificant on the day, which is exactly why people abandon them — the payoff is delayed and then sudden. The same maths works against you with small bad choices.', 'The Compound Effect — Darren Hardy', '["Pick one small daily choice you make that helps you, and one that harms you.","Multiply each by 365. Write what a year of each adds up to.","Decide which one you will keep and which you will swap.","Do your habit today and tick it off."]'::jsonb, 'What do your two small choices add up to over a year?', 0, false, '[]'::jsonb),
  ('33721a9a-e30c-5b65-aa47-b904fe2bfd83', 22, 'Review your foundation', 'Getting one percent better every day adds up to something very large over a year, and one percent worse adds up to almost nothing left. Habits are the compound interest of self-improvement. Three weeks of showing up is the foundation everything else will stand on.', 'Atomic Habits — James Clear (the power of tiny gains)', '["Count your ticks out of 22.","Write the three things that made it easiest to show up.","Write the one thing that most often got in the way, and a fix for it.","Decide whether your two-minute version still feels right, or is ready to grow slightly.","Do your habit today and tick it off."]'::jsonb, 'How many of 22 days did you complete, and what will you change for the next phase?', 0, false, '[]'::jsonb),
  ('33721a9a-e30c-5b65-aa47-b904fe2bfd83', 23, 'Raise the bar by a notch', 'People stay motivated when they work on tasks right at the edge of their ability — not too hard, not too easy. Now that showing up is established, a small increase keeps the habit interesting. Just a little beyond where you are now.', 'Atomic Habits — James Clear (the Goldilocks Rule)', '["Look at what you do now for your habit.","Increase it by a small amount: a few more minutes, one more page, one more repetition.","It should feel slightly challenging but clearly doable.","Keep the two-minute version as your fallback for bad days.","Do your habit today and tick it off."]'::jsonb, 'What did you raise your habit to, and how did the new level feel?', 0, false, '[]'::jsonb),
  ('33721a9a-e30c-5b65-aa47-b904fe2bfd83', 24, 'Go past the point where you want to stop', 'When your mind tells you that you are finished, you have usually used well under half of what you have. The feeling of being done is a safety limit, not the truth. Pushing a little beyond it, regularly, moves the limit.', 'Can''t Hurt Me — David Goggins (the 40% rule)', '["During today''s habit, notice the exact moment you want to stop.","Do five to ten percent more: one more minute, one more page, one more round.","Notice that you were able to.","Write down where the ''stop'' signal came and how far you went past it."]'::jsonb, 'When did your mind say stop, and how much further did you actually go?', 0, false, '[]'::jsonb),
  ('33721a9a-e30c-5b65-aa47-b904fe2bfd83', 25, 'Fill your cookie jar', 'In hard moments it helps to remember the hard things you have already overcome. Keeping a mental store of past victories — and reaching into it when you want to quit — reminds you who you are. You have more evidence than you think.', 'Can''t Hurt Me — David Goggins (the cookie jar)', '["Write a list of at least ten things you have overcome or achieved: big, small, recent, old.","Include the days you showed up on this course when you did not feel like it.","Keep the list on your phone.","The next time you want to skip, read three of them first.","Do your habit today and tick it off."]'::jsonb, 'What are three ''cookies'' from your jar that prove you can do hard things?', 0, false, '[]'::jsonb),
  ('33721a9a-e30c-5b65-aa47-b904fe2bfd83', 26, 'Forgive the slip, keep the habit', 'When people break a resolution, guilt and self-criticism make them more likely to give up completely, not less: ''I''ve blown it, so what the hell.'' Treating a slip with the kindness you would show a friend is what gets people back on track. Self-compassion is not weakness; it is what keeps you going.', 'The Willpower Instinct — Kelly McGonigal (the what-the-hell effect)', '["Think of the last time you slipped, on this habit or another.","Write what you said to yourself then.","Rewrite it as you would say it to a friend in the same situation.","Decide now what you will say to yourself after the next slip.","Do your habit today and tick it off."]'::jsonb, 'What will you say to yourself the next time you slip?', 0, false, '[]'::jsonb),
  ('33721a9a-e30c-5b65-aa47-b904fe2bfd83', 27, 'Surf the urge', 'An urge is like a wave: it builds, peaks and passes whether or not you act on it. Trying to suppress it makes it stronger. Watching it with curiosity for a few minutes — noticing where you feel it, how it changes — lets it fade by itself.', 'The Willpower Instinct — Kelly McGonigal (surfing the urge)', '["Wait for an urge today: to skip your habit, check your phone, snack, quit.","Do not fight it and do not obey it. Set a timer for ten minutes.","Notice where in your body you feel it. Breathe slowly.","When the timer ends, decide again.","Do your habit today and tick it off."]'::jsonb, 'What urge did you surf, and what had happened to it after ten minutes?', 0, false, '[]'::jsonb),
  ('33721a9a-e30c-5b65-aa47-b904fe2bfd83', 28, 'Say it to someone who believes in it', 'Habits survive stress when people believe change is possible, and that belief is far easier to hold in the company of others. A group, or even one other person, turns a private wish into a shared commitment. Change becomes real when you see it in other people''s eyes.', 'The Power of Habit — Charles Duhigg (belief and community)', '["Choose one person who will take your goal seriously.","Tell them what you are doing and that you are on Day 28 of 66.","Ask them to check in with you once a week.","Do your habit today and tick it off."]'::jsonb, 'Who did you tell, and how did they respond?', 0, false, '[]'::jsonb),
  ('33721a9a-e30c-5b65-aa47-b904fe2bfd83', 29, 'Plan for your hardest moment', 'Willpower holds up best when you have decided in advance what you will do at the moment it is tested. Writing a specific plan for the point where you usually give in turns a struggle into a routine. You act on the plan instead of deciding under pressure.', 'The Power of Habit — Charles Duhigg (planning for inflection points)', '["Name the situation in which you are most likely to skip: tired after work, travelling, a bad mood, a busy day.","Write: “When [situation] happens, I will [exact action].”","Make the action concrete and small.","Rehearse it once in your head.","Do your habit today and tick it off."]'::jsonb, 'What is your hardest moment, and what is your written plan for it?', 0, false, '[]'::jsonb),
  ('33721a9a-e30c-5b65-aa47-b904fe2bfd83', 30, 'Lock in your future self', 'A commitment device is a choice you make now that controls your actions later. It works by making the bad option harder or more costly while your good intentions are still strong. You are making the decision once, in advance, for the version of you who will be tempted.', 'Atomic Habits — James Clear (commitment devices)', '["Find one way to lock in tomorrow''s good behaviour today.","Examples: pay for a class in advance, schedule a session with a friend, set an app limit, pack your bag and leave it by the door.","Set it up now.","Do your habit today and tick it off."]'::jsonb, 'What commitment device did you set up, and what does it make harder to avoid?', 0, false, '[]'::jsonb),
  ('33721a9a-e30c-5b65-aa47-b904fe2bfd83', 31, 'Sign a habit contract', 'We repeat what is rewarded and avoid what is punished, and few things sting more than letting someone down. Writing down what you commit to, naming a consequence and having another person sign it adds an immediate cost to skipping. Knowing someone is watching is a strong motivator.', 'Atomic Habits — James Clear (the habit contract)', '["Write one paragraph: what you will do, how often, until Day 66.","Add a consequence for missing two days in a row that you would genuinely dislike.","Ask your accountability person to sign it or reply “agreed”.","Keep it where you can see it.","Do your habit today and tick it off."]'::jsonb, 'What consequence did you write into your contract, and who agreed to hold you to it?', 0, false, '[]'::jsonb),
  ('33721a9a-e30c-5b65-aa47-b904fe2bfd83', 32, 'Do something that sucks', 'The mind gets tougher the same way hands do: through friction. Deliberately doing something uncomfortable each day builds a callus over the part of you that wants comfort above everything. The discomfort does not have to be big; it has to be chosen.', 'Can''t Hurt Me — David Goggins (callousing your mind)', '["Choose one small uncomfortable thing unrelated to your habit: a cold finish to your shower, the stairs instead of the lift, the chore you hate, the call you are avoiding.","Do it first.","Notice that the dread was worse than the thing.","Do your habit today and tick it off."]'::jsonb, 'What uncomfortable thing did you do on purpose, and how did it compare with the dread beforehand?', 0, false, '[]'::jsonb),
  ('33721a9a-e30c-5b65-aa47-b904fe2bfd83', 33, 'Do more than anyone expects', 'When someone doubts you or sets a standard, meet it and then go far beyond. The effort itself shifts the balance: it earns respect and, more importantly, proves to you what you are capable of. Excellence is a response.', 'Can''t Hurt Me — David Goggins (taking souls)', '["Pick one task today that someone else is expecting from you.","Do it to a standard clearly above what was asked: earlier, more thorough, better finished.","Do not announce it. Let the work speak.","Do your habit today and tick it off."]'::jsonb, 'What did you over-deliver on today, and how did it feel to exceed the standard?', 0, false, '[]'::jsonb),
  ('33721a9a-e30c-5b65-aa47-b904fe2bfd83', 34, 'Write your why', 'Willpower alone runs out. What keeps people going through boredom and difficulty is a reason that matters deeply to them. When the why is strong enough, the how becomes something you are prepared to endure.', 'The Compound Effect — Darren Hardy (why-power)', '["Write why you started this habit.","Ask “and why does that matter?” three more times, writing each answer.","Underline the last answer. That is your real why.","Put it at the top of your tracker.","Do your habit today and tick it off."]'::jsonb, 'What is the why you reached after asking four times?', 0, false, '[]'::jsonb),
  ('33721a9a-e30c-5b65-aa47-b904fe2bfd83', 35, 'Line up your goals', 'Grit is passion and perseverance for long-term goals, and it shows in how well your everyday tasks serve one overriding aim. Small goals are means to larger ones. When they all point the same way, effort accumulates instead of scattering.', 'Grit — Angela Duckworth (the goal hierarchy)', '["At the top of a page, write the one long-term aim that matters most to you.","Below it, write the two or three mid-level goals that serve it.","At the bottom, write this week''s actions, including your habit.","Cross out one activity that serves nothing on the page.","Do your habit today and tick it off."]'::jsonb, 'What is at the top of your hierarchy, and what did you cross out?', 0, false, '[]'::jsonb),
  ('33721a9a-e30c-5b65-aa47-b904fe2bfd83', 36, 'Practise your weakest part', 'Experts improve through deliberate practice: choosing a specific weakness, giving it full concentration, getting feedback and repeating. It is less pleasant than doing what you are already good at, which is why most people avoid it. A short, focused dose beats a long comfortable one.', 'Grit — Angela Duckworth (deliberate practice)', '["Name the weakest part of your habit: the start, the middle, the quality, the consistency.","Spend ten focused minutes on only that part today.","Get feedback: time it, record it, or ask someone.","Write one thing to adjust tomorrow."]'::jsonb, 'What was your weakest part, and what did ten focused minutes teach you?', 0, false, '[]'::jsonb),
  ('33721a9a-e30c-5b65-aa47-b904fe2bfd83', 37, 'Get up when the alarm goes', 'Discipline starts with the first decision of the day. When the alarm sounds, there is a moment of weakness where you negotiate with yourself; getting up without the negotiation is a win before anything else has happened. That small victory sets the tone.', 'Discipline Equals Freedom — Jocko Willink', '["Set tomorrow''s alarm tonight and put it out of arm''s reach.","When it rings, stand up immediately. No snooze, no negotiating.","Do something physical for one minute: stretch, a glass of water, cold water on the face.","Notice how the rest of the morning goes.","Do your habit today and tick it off."]'::jsonb, 'Did you get up the moment the alarm rang, and what did that first win do for your morning?', 0, false, '[]'::jsonb),
  ('33721a9a-e30c-5b65-aa47-b904fe2bfd83', 38, 'Answer a setback with ''Good''', 'When something goes wrong, there is nearly always something useful in it: a lesson, more time to prepare, a chance to get stronger. Answering a setback with a single word — good — points you straight at that opportunity instead of at self-pity. It is a habit of mind you can practise.', 'Discipline Equals Freedom — Jocko Willink', '["Notice the first thing that goes wrong today, big or small.","Say “Good.” out loud or in your head.","Then finish the sentence: “Good, because now I can…”","Act on it.","Do your habit today and tick it off."]'::jsonb, 'What went wrong today, and how did you finish “Good, because now I can…”?', 0, false, '[]'::jsonb),
  ('33721a9a-e30c-5b65-aa47-b904fe2bfd83', 39, 'Stack a second habit', 'One of the best ways to build a new habit is to attach it to one you already do. Each established habit becomes the cue for the next, and a chain of small behaviours forms. Your first habit is now strong enough to carry another.', 'Atomic Habits — James Clear (habit stacking)', '["Choose a second tiny habit, two minutes at most.","Write: “After I [your current habit], I will [new tiny habit].”","Do both today, in that order.","Celebrate after the second one."]'::jsonb, 'What second habit did you stack, and what is your new sentence?', 0, false, '[]'::jsonb),
  ('33721a9a-e30c-5b65-aa47-b904fe2bfd83', 40, 'Don''t reward good with bad', 'After doing something virtuous, people often feel they have earned permission to indulge — and undo the progress. The trap is treating the habit as a sacrifice that deserves compensation. Remembering why you did it, instead of congratulating yourself for being good, breaks the pattern.', 'The Willpower Instinct — Kelly McGonigal (moral licensing)', '["Watch today for the thought “I''ve been good, so I deserve…”.","When it appears, ask: what am I actually trying to become?","Choose a reward that supports that person instead of undoing it.","Do your habit today and tick it off."]'::jsonb, 'When did “I deserve it” show up today, and what did you choose instead?', 0, false, '[]'::jsonb),
  ('33721a9a-e30c-5b65-aa47-b904fe2bfd83', 41, 'Write to your future self', 'We tend to treat our future selves like strangers, handing them the consequences of today''s choices. The more connected and real that future person feels, the easier it is to act in their interest now. Picturing them vividly is a self-control tool.', 'The Willpower Instinct — Kelly McGonigal (future-self continuity)', '["Write a short letter to yourself on Day 66.","Describe what you are doing now, what is hard, and what you hope they will thank you for.","Then write three lines back, from that future self to you today.","Keep the letter to read on Day 66.","Do your habit today and tick it off."]'::jsonb, 'What do you hope your Day-66 self will thank you for?', 0, false, '[]'::jsonb),
  ('33721a9a-e30c-5b65-aa47-b904fe2bfd83', 42, 'Bookend your day', 'You cannot control the middle of your day, but you can almost always control how it starts and ends. A fixed morning and evening routine protects your momentum from whatever happens in between. Consistency in the bookends is what keeps the rhythm going.', 'The Compound Effect — Darren Hardy (momentum and routines)', '["Write a morning routine of three steps that takes under 15 minutes.","Write an evening routine of three steps, including preparing for tomorrow.","Put your habit inside one of them.","Run both today."]'::jsonb, 'What are your three morning steps and three evening steps?', 0, false, '[]'::jsonb),
  ('33721a9a-e30c-5b65-aa47-b904fe2bfd83', 43, 'Trust the plateau', 'Progress is not a straight line. Habits often seem to make no difference until you cross a threshold, like ice that stays solid degree after degree and then melts. The work you did in the flat stretch was not wasted; it was being stored.', 'Atomic Habits — James Clear (the plateau of latent potential)', '["Write down what you expected to feel or see by now.","Write what you actually see.","List the invisible things that have changed: how automatic it is, how you talk about yourself, how fast you recover from a miss.","Do your habit today and tick it off."]'::jsonb, 'What has changed beneath the surface that you cannot yet see in results?', 0, false, '[]'::jsonb),
  ('33721a9a-e30c-5b65-aa47-b904fe2bfd83', 44, 'Write an after-action report', 'After any effort, successful or not, write an honest account: what went right, what went wrong, and what to fix. It turns experience into something you can use. Skipping the review means repeating the same mistakes with more confidence.', 'Can''t Hurt Me — David Goggins (the after-action report)', '["Count your ticks for days 23–44.","Write three headings: WENT WELL, WENT WRONG, FIX.","Put at least three points under each. Be blunt.","Choose one fix to start tomorrow.","Do your habit today and tick it off."]'::jsonb, 'What is the bluntest line in your after-action report, and what fix starts tomorrow?', 0, false, '[]'::jsonb),
  ('33721a9a-e30c-5b65-aa47-b904fe2bfd83', 45, 'Focus on the system, not the goal', 'Winners and losers often have the same goals; what separates them is the system they follow each day. A goal sets a direction, but the result comes from the process. You do not rise to the level of your goals — you fall to the level of your systems.', 'Atomic Habits — James Clear (forget about goals, focus on systems)', '["Write your goal in one line.","Underneath, describe your system: what you do, when, where, with what cue, and how you track it.","Find the weakest link in that system.","Strengthen it today.","Do your habit today and tick it off."]'::jsonb, 'What is the weakest link in your system, and what did you do to strengthen it?', 0, false, '[]'::jsonb),
  ('33721a9a-e30c-5b65-aa47-b904fe2bfd83', 46, 'Let it grow by itself', 'Tiny habits grow in the way plants do: when the roots are established, they expand naturally. You do not have to force yourself to do more; on days when you want to, you do extra, and the baseline stays tiny. Growth comes from wanting to, not from having to.', 'Tiny Habits — BJ Fogg (growing and multiplying habits)', '["Do your habit today.","When you reach your usual stopping point, ask honestly: do I want to do more?","If yes, continue. If no, stop and celebrate anyway.","Note which it was."]'::jsonb, 'Did you want to do more today, and what does that tell you about where the habit is?', 0, false, '[]'::jsonb),
  ('33721a9a-e30c-5b65-aa47-b904fe2bfd83', 47, 'Troubleshoot with B = MAP', 'A behaviour happens when three things meet at the same moment: motivation, ability and a prompt. If a habit is not happening, one of them is missing. Do not start by trying to raise motivation — check the prompt first, then make it easier.', 'Tiny Habits — BJ Fogg (the Fogg Behavior Model)', '["Think of the last day your habit did not happen, or felt hard.","Check the prompt: was there a clear reminder at the right moment?","Check ability: was it too hard, too long, too inconvenient?","Only then check motivation.","Fix the first one that failed.","Do your habit today and tick it off."]'::jsonb, 'Which was missing — prompt, ability or motivation — and what did you fix?', 0, false, '[]'::jsonb),
  ('33721a9a-e30c-5b65-aa47-b904fe2bfd83', 48, 'Rewrite one bad habit', 'You cannot simply extinguish a bad habit; you can change it. Keep the same cue and deliver the same reward, but insert a new routine in between. Almost any behaviour can be reshaped once you see the loop it runs on.', 'The Power of Habit — Charles Duhigg (the golden rule of habit change)', '["Pick one habit you would like to change.","Write its cue (what happens just before) and its reward (what you really get from it).","Choose a new routine that gives the same reward from the same cue.","Use the new routine the next time the cue appears.","Do your habit today and tick it off."]'::jsonb, 'What cue, new routine and reward did you write down for the habit you are changing?', 0, false, '[]'::jsonb),
  ('33721a9a-e30c-5b65-aa47-b904fe2bfd83', 49, 'Make it satisfying now', 'What is immediately rewarded gets repeated; what is immediately punished gets avoided. Good habits usually pay later, so they need a small reward now to carry them until the real results arrive. The ending is the part of any experience we remember.', 'Atomic Habits — James Clear (4th law: make it satisfying)', '["Choose an immediate reward that fits who you want to be: transferring a small amount to savings, a mark on a wall chart, a favourite tea, five minutes of music.","Give it to yourself right after the habit.","Make sure the reward does not work against the habit.","Do your habit today and tick it off."]'::jsonb, 'What immediate reward did you choose, and how did the habit feel with it?', 0, false, '[]'::jsonb),
  ('33721a9a-e30c-5b65-aa47-b904fe2bfd83', 50, 'Do it now', 'The moment to begin is not when you feel ready or when conditions are right. Hesitation feeds on itself: the longer you think about starting, the heavier it gets. The answer to where and when to start is here and now.', 'Discipline Equals Freedom — Jocko Willink', '["Write down one thing you have been postponing for more than a week.","Within the next five minutes, do the first step of it.","Do not plan, research or tidy first.","Then do your habit immediately afterwards, without a pause."]'::jsonb, 'What had you been postponing, and what happened when you started within five minutes?', 0, false, '[]'::jsonb),
  ('33721a9a-e30c-5b65-aa47-b904fe2bfd83', 51, 'Be uncommon among the uncommon', 'It is one thing to stand out among people who are not trying. The real test is to keep raising your standard when you are already doing well and nobody would blame you for coasting. Staying hungry after success is rarer than achieving it.', 'Can''t Hurt Me — David Goggins (uncommon amongst uncommon)', '["Name the area where you are already good enough to coast.","Write the standard you currently hold yourself to there.","Raise it by one clear notch.","Meet the new standard once today.","Do your habit today and tick it off."]'::jsonb, 'Where were you coasting, and what new standard did you set?', 0, false, '[]'::jsonb),
  ('33721a9a-e30c-5b65-aa47-b904fe2bfd83', 52, 'Connect it to someone else', 'People who persevere for years usually believe their work matters to someone beyond themselves. Purpose — the intention to contribute to the wellbeing of others — is one of the deepest sources of staying power. A habit that serves only you is easier to drop.', 'Grit — Angela Duckworth (purpose)', '["Ask: who benefits, directly or indirectly, when I keep this habit?","Write their name or names.","Write one sentence on how your habit makes their life better.","Do today''s habit with that person in mind."]'::jsonb, 'Who else benefits from your habit, and how?', 0, false, '[]'::jsonb),
  ('33721a9a-e30c-5b65-aa47-b904fe2bfd83', 53, 'Praise your effort, not your talent', 'Praising ability teaches people to protect an image and avoid anything they might fail at; praising effort and strategy teaches them to seek challenge. The way you talk to yourself after a result has the same effect. Notice the process, not the label.', 'Mindset — Carol S. Dweck', '["After today''s habit, describe what you did without calling yourself good or bad at it.","Name the effort or the strategy: “I started even though I was tired”, “I broke it into steps.”","Do the same when you speak to someone else today.","Do your habit today and tick it off."]'::jsonb, 'What effort or strategy did you praise in yourself today?', 0, false, '[]'::jsonb),
  ('33721a9a-e30c-5b65-aa47-b904fe2bfd83', 54, 'Arrange your life so you need less willpower', 'People with the most self-control are not the ones who resist temptation most heroically; they are the ones who face it least. They spend less time in tempting situations and so need discipline less often. The goal is a life where the right thing is the easy thing.', 'Atomic Habits — James Clear (the secret to self-control)', '["List the three situations where you most often need willpower.","For each, write a change that removes the temptation instead of resisting it.","Make one of those changes today.","Do your habit today and tick it off."]'::jsonb, 'Which temptation did you remove today, and how?', 0, false, '[]'::jsonb),
  ('33721a9a-e30c-5b65-aa47-b904fe2bfd83', 55, 'Hold a review', 'Habits make things automatic, and what is automatic stops being examined. A regular review catches the small slips before they become the new normal and keeps you aware of whether you are still improving. Reflection is what stops a good habit from turning into mindless repetition.', 'Atomic Habits — James Clear (reflection and review)', '["Answer three questions in writing: What went well in the last ten days? What didn''t? What did I learn?","Check whether your habit still matches the person you want to be.","Adjust one detail.","Put a monthly review in your calendar.","Do your habit today and tick it off."]'::jsonb, 'What did your review show, and what detail did you adjust?', 0, false, '[]'::jsonb),
  ('33721a9a-e30c-5b65-aa47-b904fe2bfd83', 56, 'Tell wanting from enjoying', 'The brain''s reward system produces desire, not satisfaction: it promises that the next thing will make you happy, and often it does not. Many of the things we chase feel better in anticipation than in reality. Checking whether a reward actually delivers frees you from quite a few of them.', 'The Willpower Instinct — Kelly McGonigal (the promise of reward)', '["Pick one thing you often crave: scrolling, a snack, online shopping.","Before you do it today, rate how good you expect it to feel, from 1 to 10.","Do it slowly and pay attention. Rate how it actually felt.","Do the same for your habit."]'::jsonb, 'How did the expected and actual scores compare — for the craving, and for your habit?', 0, false, '[]'::jsonb),
  ('33721a9a-e30c-5b65-aa47-b904fe2bfd83', 57, 'Choose your willpower role model', 'Self-control and its absence both spread through groups: we catch the goals and the lapses of the people we watch. Thinking of someone with strong self-control can lift your own. You can decide whose example you are exposed to.', 'The Willpower Instinct — Kelly McGonigal (willpower is contagious)', '["Name one person, known to you or not, whose discipline you admire.","Write three things they do that you want to copy.","The next time you are tempted to skip, ask what they would do.","Reduce your exposure to one person or feed that pulls you the other way.","Do your habit today and tick it off."]'::jsonb, 'Who is your willpower role model, and what would they have done in your hardest moment this week?', 0, false, '[]'::jsonb),
  ('33721a9a-e30c-5b65-aa47-b904fe2bfd83', 58, 'Adopt the hard thing rule', 'A simple family rule builds perseverance: everyone does one hard thing that needs daily deliberate practice, you may not quit on a bad day — only at a natural stopping point — and you choose the hard thing yourself. It teaches finishing what you start.', 'Grit — Angela Duckworth (the Hard Thing Rule)', '["Write your hard thing. It may be your current habit.","Write your natural stopping point: Day 66.","Write the rule: “I do not quit on a bad day.”","Tell the people you live with, and invite them to choose their own hard thing.","Do your habit today and tick it off."]'::jsonb, 'What is your hard thing, and who did you invite to pick their own?', 0, false, '[]'::jsonb),
  ('33721a9a-e30c-5b65-aa47-b904fe2bfd83', 59, 'Count your votes', 'Each time you perform a habit you cast a vote for the type of person you wish to become. No single vote decides the matter, but as they pile up, the evidence changes what you believe about yourself. By now you have a real record.', 'Atomic Habits — James Clear (identity-based habits)', '["Count every tick on your tracker.","Write: “I have voted [number] times for being someone who…”","Reread your Day 1 sentence. Is it truer now?","Write a new version of it in the present tense: “I am…”","Do your habit today and tick it off."]'::jsonb, 'How many votes have you cast, and what is your new “I am…” sentence?', 0, false, '[]'::jsonb),
  ('33721a9a-e30c-5b65-aa47-b904fe2bfd83', 60, 'Ask ''what if?''', 'When doubt says you cannot do something, a quiet question cuts through it: what if you could? It does not promise success; it opens a door that fear had closed. Most limits are untested assumptions.', 'Can''t Hurt Me — David Goggins (What if?)', '["Write one thing you have assumed is beyond you.","Under it, write “What if I could?”","List the first three steps you would take if it were possible.","Take the first one today.","Do your habit today and tick it off."]'::jsonb, 'What ''impossible'' thing did you question, and what first step did you take?', 0, false, '[]'::jsonb),
  ('33721a9a-e30c-5b65-aa47-b904fe2bfd83', 61, 'Show up when it''s boring', 'The greatest threat to success is not failure but boredom. Anyone can work hard when they feel inspired; what separates the best is that they keep going when the work has stopped being exciting. Falling in love with repetition is the real skill.', 'Atomic Habits — James Clear (how to stay motivated)', '["Do your habit today exactly as usual, with no music, no novelty, no reward.","Notice the boredom without fixing it.","Find one small detail to do slightly better than yesterday.","Tick the box."]'::jsonb, 'How did it feel to do the habit with nothing to make it interesting, and what detail did you improve?', 0, false, '[]'::jsonb),
  ('33721a9a-e30c-5b65-aa47-b904fe2bfd83', 62, 'Choose your next keystone', 'A single well-chosen habit can start a chain reaction through the rest of your life, because it changes how you see yourself. The first one is nearly automatic now. Choosing the next deliberately keeps the momentum moving in a direction you picked.', 'The Power of Habit — Charles Duhigg (keystone habits)', '["List three habits you would like next.","For each, ask: which one would make the others easier?","Choose that one.","Write its two-minute version and its cue.","Do not start it until Day 66 is done.","Do your habit today and tick it off."]'::jsonb, 'What is your next keystone habit, and what are its cue and two-minute version?', 0, false, '[]'::jsonb),
  ('33721a9a-e30c-5b65-aa47-b904fe2bfd83', 63, 'Take the initiative', 'Waiting to be told, or waiting for conditions to improve, hands control to circumstances. The alternative is to be proactive by default: see what needs doing and move first. Aggressive here does not mean angry — it means not hesitating.', 'Discipline Equals Freedom — Jocko Willink (default: aggressive)', '["Find one problem today that you have been waiting for someone else to solve.","Take the first action yourself, without being asked.","Do it early in the day.","Do your habit today and tick it off."]'::jsonb, 'What problem did you move on first today, and what happened?', 0, false, '[]'::jsonb),
  ('33721a9a-e30c-5b65-aa47-b904fe2bfd83', 64, 'Project one year ahead', 'The compound effect is always working, for you or against you. Small disciplines repeated daily are barely visible for months and then produce a gap that cannot be closed quickly. Looking a year ahead shows you what today''s choice is really worth.', 'The Compound Effect — Darren Hardy', '["Work out what a year of your habit adds up to: pages, kilometres, hours, dollars.","Write that number large.","Write what a year of not doing it would add up to.","Put the first number where you will see it daily.","Do your habit today and tick it off."]'::jsonb, 'What does one year of your habit add up to?', 0, false, '[]'::jsonb),
  ('33721a9a-e30c-5b65-aa47-b904fe2bfd83', 65, 'Help someone else start', 'The same method that changes your own behaviour works for helping other people change theirs: start tiny, find a good prompt, celebrate. Helping someone else design a habit also deepens your own understanding of it. Change spreads through people.', 'Tiny Habits — BJ Fogg (changing together)', '["Think of someone who has mentioned wanting to change something.","Offer to help. Ask what they want, then help them shrink it to something tiny.","Help them choose a prompt: “After I…, I will…”","Tell them to celebrate each time.","Do your habit today and tick it off."]'::jsonb, 'Who did you help, and what tiny habit and prompt did you design together?', 0, false, '[]'::jsonb),
  ('33721a9a-e30c-5b65-aa47-b904fe2bfd83', 66, 'Day 66: never stop making small improvements', 'Success is not a finish line to cross but a system to keep refining. One small change will not transform your life, yet one after another, each added to the last, eventually tips the scale. You have built the proof; the question now is what you add next.', 'Atomic Habits — James Clear (the secret to results that last)', '["Do your habit one more time and fill the last box.","Read the letter you wrote on Day 41.","Count your total days done out of 66.","Write the three tools from this course that worked best for you.","Start the two-minute version of your next keystone habit tomorrow."]'::jsonb, 'How many of 66 days did you complete, what are your three best tools, and what habit starts tomorrow?', 0, false, '[]'::jsonb),
  ('b9e48da4-691f-5012-ad0c-6f435d1e7990', 1, 'Invite AI to one real task', 'The fastest way to learn what AI can do is to bring it into the work you already do, instead of testing it on toy questions. You are the expert in your own tasks, so you can judge its answers better than anyone. Expect it to be surprisingly good at some things and surprisingly bad at others — the only way to find that uneven edge is to try.', 'Co-Intelligence — Ethan Mollick (Principle 1: always invite AI to the table)', '["Open any AI assistant — ChatGPT, Claude or Gemini. The free version is enough for this whole course.","Pick one real thing on your to-do list today: an email to write, a plan to make, a decision to think through.","Describe it the way you would to a helpful colleague. Type: “I need help with [task]. It''s for [who]. A good result looks like [what you want]. Here is the background: [2–3 sentences].”","Read the answer, then reply at least once: “Make it shorter”, “That part is wrong because…”, or “Give me two other options.” The second answer is almost always better than the first.","Use it, edit it or throw it away — then note one thing it did well and one thing it got wrong."]'::jsonb, 'What task did you bring to AI, and where was it better or worse than you expected?', 0, true, '[]'::jsonb),
  ('b9e48da4-691f-5012-ad0c-6f435d1e7990', 2, 'Give it a role and an audience', 'An AI answers as a bland average of everything it has read unless you tell it who to be. Treating it like a person — and saying what kind of person — pulls out a more specific, more useful voice. Telling it who the answer is for matters just as much as telling it who is speaking.', 'Co-Intelligence — Ethan Mollick (Principle 3: treat AI like a person, and tell it what kind of person it is)', '["Pick a question you would normally type into a search engine, for example how to plan meals for the week or how to ask for a raise.","Ask it plainly first and keep the answer.","Start a new chat and ask again with a role and an audience: “You are a [specific expert, e.g. a dietitian who works with busy parents]. I am [who you are and your situation]. Explain it for someone who [your level]. Be practical and specific.”","Put the two answers side by side. Mark what changed: the detail, the tone, the assumptions about you.","Save the role line that worked — you will reuse it."]'::jsonb, 'What role and audience did you give the AI, and what was the biggest difference between the two answers?', 0, true, '[]'::jsonb),
  ('b9e48da4-691f-5012-ad0c-6f435d1e7990', 3, 'Catch it being wrong', 'AI can sound completely confident while being incorrect: it produces what is plausible, not what is checked. That is why the human has to stay in the loop — not to accept or reject AI wholesale, but to verify where it matters. Knowing how it fails is what makes it safe to rely on.', 'Co-Intelligence — Ethan Mollick (Principle 2: be the human in the loop)', '["Ask the AI about something you know extremely well: your job, your home town, your hobby, your own field of study.","Ask for specifics that can be checked: “Give me five precise facts with names, dates or numbers.”","Go through the answer line by line and find at least one thing that is wrong, outdated or invented.","Tell it: “This part is incorrect: [quote it]. Why did you say that?” Notice whether it corrects itself or simply agrees with whatever you say.","Write your personal rule: the kinds of facts you will always double-check before using an AI answer."]'::jsonb, 'What did the AI get wrong, and what is your rule for checking its answers from now on?', 0, false, '[]'::jsonb),
  ('b9e48da4-691f-5012-ad0c-6f435d1e7990', 4, 'Write a five-part prompt', 'Working well with AI looks less like searching and more like briefing a capable new colleague who knows nothing about your situation. The more context and constraints you give, the less it has to guess — and guessing is where generic answers come from. A good brief is the single biggest upgrade to your results.', 'Co-Intelligence — Ethan Mollick (on giving AI context and constraints)', '["Choose a task you actually need done this week.","Write your prompt in five labelled parts. ROLE: who the AI should be. CONTEXT: your situation in 2–4 sentences. TASK: exactly what you want. FORMAT: bullets, table, length, tone. CONSTRAINTS: what to avoid and what must be included.","Example: “ROLE: You are an experienced travel planner. CONTEXT: Two adults, 4 days in Lisbon in May, we like food and walking, budget about $150 a day. TASK: Plan the trip day by day. FORMAT: A table with morning, afternoon, evening. CONSTRAINTS: No more than one museum a day, no tourist-trap restaurants.”","Send it. Then send the lazy one-line version of the same request in a new chat and compare.","Save the five headings as a note on your phone. This is your template for the rest of the course."]'::jsonb, 'Paste your five-part prompt. What did the structured version give you that the one-liner did not?', 0, false, '[]'::jsonb),
  ('b9e48da4-691f-5012-ad0c-6f435d1e7990', 5, 'Show it examples', 'AI works from patterns, so one good example tells it more than a paragraph of description. If you want writing that sounds like you, or output in an exact shape, show it what “right” looks like. People who get consistent results rarely describe what they want — they demonstrate it.', 'Co-Intelligence — Ethan Mollick (on working with AI as a co-writer)', '["Find two or three short things you wrote that sound like you: messages, emails, captions, notes.","Type: “Here are examples of how I write. Example 1: [paste]. Example 2: [paste]. Example 3: [paste]. Describe my style in five bullet points.”","Check its description. Correct it: “Not quite — I never use exclamation marks, and I keep sentences short.”","Now ask: “Using exactly that style, write [something you need: a message to a friend, a product description, a post].”","Try the same trick for format: paste one example of a layout you like and say “Give me the answer in this same structure.”"]'::jsonb, 'How did the AI describe your writing style, and how close was its version to something you would really send?', 0, false, '[]'::jsonb),
  ('b9e48da4-691f-5012-ad0c-6f435d1e7990', 6, 'Make it think, and make it ask you questions', 'AI gives better answers when it works through a problem in steps instead of jumping to a conclusion, and when it is missing less information about you. The simplest way to fix both is to ask for its reasoning and to let it interview you first. You stop being someone who types a request and become someone who runs a conversation.', 'Co-Intelligence — Ethan Mollick (on prompting AI to reason step by step)', '["Pick a real decision you are facing: a purchase, a move, a job choice, a plan for the month.","Type: “I need to decide [decision]. Before you answer, ask me the five questions you most need answered to give good advice. Ask them one at a time.”","Answer its questions honestly.","Then type: “Now think it through step by step. List the options, the trade-offs of each, and what you are assuming. Give your recommendation only at the end.”","Push back once: “What is the strongest argument against your recommendation?”"]'::jsonb, 'Which question from the AI made you think hardest, and did its final recommendation change your mind?', 0, false, '[]'::jsonb),
  ('b9e48da4-691f-5012-ad0c-6f435d1e7990', 7, 'Write a hard email in your own voice', 'AI works best as an amplifier: it gives you a fast first draft and options you would not have thought of, while you stay the author who decides what is true and what gets sent. The time you save is not in typing — it is in getting past the blank page. Your name is on the message, so the judgment has to be yours.', 'Impromptu — Reid Hoffman (on AI as a co-pilot that amplifies human work)', '["Choose an email or message you have been putting off: a complaint, a follow-up, a no, an awkward request.","Give the full brief: “Write an email to [who, and your relationship]. Goal: [what you want to happen]. Facts: [the details]. Tone: [firm but polite / warm / brief]. Keep it under 120 words.”","Paste one of your own emails and add: “Match this writing style.”","Ask for range: “Give me three versions: one direct, one warm, one very short.”","Build your final version from the best lines, then ask: “Read this as the recipient. What could be misunderstood or sound rude?” Fix it.","Check every fact, name and date yourself, then send it."]'::jsonb, 'What email did you finally send, and which part did you change by hand before sending it?', 0, false, '[]'::jsonb),
  ('b9e48da4-691f-5012-ad0c-6f435d1e7990', 8, 'Research a topic and check the sources', 'AI makes prediction cheap: it can tell you in seconds what an answer probably is. That makes the parts it cannot do — judging what matters and checking what is true — more valuable, not less. Good research with AI means letting it gather, and keeping the verifying for yourself.', 'Prediction Machines — Ajay Agrawal, Joshua Gans & Avi Goldfarb', '["Pick something you genuinely want to understand this week: a health question, a purchase, a news story, a skill.","Use an assistant that can search the web (turn on Search or Web in ChatGPT, Gemini, Copilot or Perplexity).","Type: “Research [topic]. Give me a summary in plain language, the three points experts agree on, the two points they disagree on, and a link to a source for every claim.”","Open at least two of the links. Confirm that each page really says what the AI claimed. Note any link that is broken, irrelevant or says something different.","Ask: “What is the best evidence against this summary?” and “Which of these sources is least reliable, and why?”"]'::jsonb, 'What did you research, and did the sources actually say what the AI claimed they said?', 0, false, '[]'::jsonb),
  ('b9e48da4-691f-5012-ad0c-6f435d1e7990', 9, 'Compare options in a table and decide', 'Every decision has two parts: predicting what will happen, and judging what you want. AI is good at the first and has no access to the second unless you supply it. The better you describe what matters to you, the more useful its comparison becomes.', 'Prediction Machines — Ajay Agrawal, Joshua Gans & Avi Goldfarb', '["Choose a real choice between two to four options: phones, courses, cities, plans, tools.","List your criteria first, in your own words, with weights: “What matters to me: price (most important), battery life, camera, how long it will last.”","Type: “Compare [options] in a table using these criteria: [list]. Score each from 1 to 5 with a one-line reason. Say where you are unsure or where your information may be out of date.”","Challenge it: “What would make the lowest-scoring option the right choice?” and “What have I left out of my criteria?”","Check the two facts that matter most to you (price, a key spec) on the official site, then make the call yourself."]'::jsonb, 'What did you decide, and which of your own criteria ended up settling it?', 0, false, '[]'::jsonb),
  ('b9e48da4-691f-5012-ad0c-6f435d1e7990', 10, 'Turn AI into your tutor', 'One-to-one tutoring is one of the most effective ways to learn, and until now almost nobody could afford it. AI can explain an idea as many times and in as many ways as you need, at exactly your level, without judging the question. The learning still happens in your head — which means you have to make it test you, not just tell you.', 'Co-Intelligence — Ethan Mollick (AI as a tutor)', '["Pick one thing you have always half-understood: compound interest, how vaccines work, a grammar rule, a concept from your job.","Type: “Explain [topic] three times: first for a 10-year-old, then for a high-school student, then for an adult professional.”","Then: “Give me a real-life analogy for it, and one common mistake people make.”","Now make it test you: “Ask me five questions, one at a time, to check I really understand. Start easy and get harder. Do not give me the answer until I have tried.”","For any question you miss, say: “Explain that part a different way.”","Finish by explaining the idea back in your own words and asking: “What did I get wrong or leave out?”"]'::jsonb, 'What did you learn today, and which quiz question showed you that you had not really understood it yet?', 0, false, '[]'::jsonb),
  ('b9e48da4-691f-5012-ad0c-6f435d1e7990', 11, 'Summarise a long document — and verify it', 'AI does not understand a task the way you do; it finds the easiest route to something that looks like a good answer. With a long document that can mean a smooth summary that skips the awkward clause or invents a detail. A summary is a map, and you still need to check it against the territory.', 'You Look Like a Thing and I Love You — Janelle Shane', '["Find a long document you have been avoiding: a contract, a report, terms and conditions, a long article or a PDF manual.","Upload the file or paste the text. Leave out anything private, such as account numbers or ID details.","Type: “Summarise this in ten bullet points. Then list: anything that costs me money, any deadline, and anything I must do. Quote the exact sentence for each item.”","Pick three of the quoted sentences and find them in the original. Confirm they exist and mean what the AI said.","Ask the questions you actually care about: “Can I cancel, and how?”, “What happens if I am late?”, “What is unusual here compared with a normal agreement of this type?”"]'::jsonb, 'What document did you summarise, and did all three quotes you checked really appear in it?', 0, false, '[]'::jsonb),
  ('b9e48da4-691f-5012-ad0c-6f435d1e7990', 12, 'Rehearse a difficult conversation', 'Getting better at anything takes practice with feedback, and most of us never get to rehearse the conversations that matter most. AI can play the other person as many times as you like and then step out of the role to coach you. It is a safe room to be clumsy in before it counts.', 'Co-Intelligence — Ethan Mollick (AI as a coach)', '["Choose a conversation you are nervous about: asking for a raise, giving feedback, saying no, a tough talk with family.","Set the scene: “Role-play with me. You are [person], who is [their personality and likely reaction]. I am going to [my goal]. Stay in character, push back realistically, and keep your replies short. I will start.”","Have the conversation for at least six turns. If your assistant has voice mode, speak it out loud.","Then type: “Step out of the role. As a communication coach, tell me three things I did well and three things to change, quoting my exact words.”","Run it once more using the feedback, and ask it to play the person in a harder mood."]'::jsonb, 'What conversation did you rehearse, and what is one sentence you will say differently in the real one?', 0, false, '[]'::jsonb),
  ('b9e48da4-691f-5012-ad0c-6f435d1e7990', 13, 'Ask questions of your own data', 'The biggest gains do not come from machines replacing people or people ignoring machines, but from the two working together in the space between. One of the skills that makes that work is knowing how to question a machine well: asking, probing and asking again until the numbers tell you something useful.', 'Human + Machine — Paul R. Daugherty & H. James Wilson (the “missing middle” and fusion skills)', '["Find a small set of your own numbers: a bank or card export, a step-count history, a budget sheet, sales figures. Remove names and account numbers first.","Upload the spreadsheet or CSV (or paste the rows) and type: “Describe this data. What does each column mean, and is anything missing or odd?”","Ask three questions you actually care about, for example: “Which three categories cost me the most?”, “What changed month to month?”, “What are the five largest single items?”","Ask for a picture: “Make a simple chart of [the most interesting result].”","Recalculate one number yourself with a calculator or a spreadsheet formula to confirm the AI got it right.","Finish with: “Based on this, what are two things I could do differently?”"]'::jsonb, 'What data did you analyse, what did it reveal, and did the number you checked by hand match?', 0, false, '[]'::jsonb),
  ('b9e48da4-691f-5012-ad0c-6f435d1e7990', 14, 'Map what AI should and should not do for you', 'AI''s abilities form a jagged frontier: some hard-looking tasks are easy for it and some easy-looking ones are beyond it, and the line is invisible until you test it. People who use it best split their work deliberately — handing over some tasks completely, weaving it into others, and keeping some entirely human. Two weeks in, you have enough experience to draw your own map.', 'Co-Intelligence — Ethan Mollick (the jagged frontier; centaurs and cyborgs)', '["List ten tasks you do in a normal week, at work and at home.","Sort each into one of three columns. AI DOES IT (I check the result). WE DO IT TOGETHER (back and forth). ONLY ME (it needs my judgment, my relationships or my values).","Ask the AI for a second opinion: “Here are my weekly tasks: [list]. For each, say how you could help and where you would probably fail.”","Pick the three best prompts you have written so far in this course and save them in one note called “My prompts”, with a line saying when to use each.","Choose one task from the AI DOES IT column and hand it over today."]'::jsonb, 'What are your three columns, and which task surprised you by landing in “Only me”?', 0, false, '[]'::jsonb),
  ('b9e48da4-691f-5012-ad0c-6f435d1e7990', 15, 'Brainstorm thirty ideas, then pick one', 'AI is tireless at producing variations, and creativity often comes from sheer volume: the more ideas on the table, the better the best one tends to be. Most of what it suggests will be ordinary. Your job is to be the editor — to spot the two that are interesting and push them further.', 'Co-Intelligence — Ethan Mollick (AI as a creative)', '["Choose something that needs ideas: a gift, a name, a side project, content to post, a weekend plan, a way to save money.","Give constraints, because constraints make ideas better: “Give me 30 ideas for [thing]. Constraints: [budget, time, audience, what I have already tried]. Make ten safe, ten unusual and ten slightly ridiculous.”","Pick your favourite three and type: “Combine ideas [numbers] into something new. Give me five variations.”","Stress-test the winner: “You are a sceptical expert. Give me the three biggest reasons this will not work, and how to fix each.”","Turn it into a first step: “What is the smallest version of this I could do in the next 48 hours?”"]'::jsonb, 'What idea did you choose, and what is the 48-hour first step?', 0, false, '[]'::jsonb),
  ('b9e48da4-691f-5012-ad0c-6f435d1e7990', 16, 'Create an image from a description', 'An image model does not know what things are; it knows which patterns tend to appear together. That is why it can produce something beautiful and then get hands, text or simple logic wrong. You get good results by describing precisely and iterating, not by expecting it to understand what you meant.', 'You Look Like a Thing and I Love You — Janelle Shane', '["Decide what you need a picture for: a birthday card, a logo idea, a post background, a room makeover idea, a phone wallpaper.","Open an image tool. The image feature inside ChatGPT, Gemini or Copilot works, as does any free image generator.","Describe it in five parts: SUBJECT, STYLE (photo, watercolour, flat illustration), LIGHTING AND COLOUR, COMPOSITION (close-up, wide, from above), and FORMAT (square, tall).","Example: “A cosy reading corner with a green armchair and a tall bookshelf, warm evening light, soft watercolour style, wide view, vertical format, no text.”","Improve it three times, changing one thing each time: “Same image, but make it morning light” or “Remove the lamp.”","Look closely for mistakes (odd hands, garbled letters, impossible objects) and fix them with one more instruction. Do not ask for real people''s faces or copy a living artist''s style."]'::jsonb, 'What image did you make, and how many rounds did it take before it matched what was in your head?', 0, false, '[]'::jsonb),
  ('b9e48da4-691f-5012-ad0c-6f435d1e7990', 17, 'Build a one-page website by describing it', 'The tools you are using today are the weakest you will ever use — they improve every few months. That changes what is worth learning: not the syntax of code, but how to describe clearly what you want built and how to judge the result. A year ago this task needed a developer; today it needs a good brief.', 'Co-Intelligence — Ethan Mollick (Principle 4: assume this is the worst AI you will ever use)', '["Decide on a simple one-page site: a personal profile, a page for a small business, an event invitation, a portfolio, a link page.","Open an assistant that can build and preview a page inside the chat: Claude (Artifacts), ChatGPT (Canvas) or Gemini (Canvas).","Write the brief: “Build a single-page website for [what]. Sections: a headline, a short description, three key points, a contact button. Style: clean, modern, [two colours], looks good on a phone. Write the real text yourself using these details: [facts about you or the business].”","Look at the preview, then improve it three times with one clear request each: “Make the headline bigger and shorter”, “Add a section with three customer quotes”, “Change the green to navy.”","Test it at phone width. Tell the AI exactly what looks wrong and ask it to fix it.","Use the tool''s Share or Publish button to get a link, and send it to one person for feedback."]'::jsonb, 'What did you build, and what was the most useful change you asked the AI to make?', 0, false, '[]'::jsonb),
  ('b9e48da4-691f-5012-ad0c-6f435d1e7990', 18, 'Make a short video with AI', 'Powerful technologies spread fast because their cost collapses: what once needed a studio and a team becomes something anyone with a phone can do. Video is going through that shift right now. The scarce skill is no longer operating the equipment — it is knowing what is worth saying in thirty seconds.', 'The Coming Wave — Mustafa Suleyman', '["Choose a 20–30 second message: a tip you know well, a product, a thank-you, a book idea, an announcement.","Get a script: “Write a 30-second video script about [topic] for [audience]. Open with a hook in the first three seconds, make one clear point, end with one call to action. About 70 words, spoken language.”","Get a shot list: “Turn this script into a storyboard of five shots. For each: what is on screen, the on-screen text, and how many seconds.”","Make it in a free tool. Easiest route: a video editor with AI features (CapCut, Canva or similar) — paste the script, let it generate captions and a voiceover, and add stock or AI-generated clips for each shot. If you have access to a text-to-video model, generate one or two shots from your storyboard descriptions.","Watch it with the sound off and then on. Fix one thing: the hook, the pace or the captions.","Export it. If you post it and it uses AI-generated footage or voice, say so."]'::jsonb, 'What was your video about, and which part took longest: the script, the visuals or the editing?', 0, false, '[]'::jsonb),
  ('b9e48da4-691f-5012-ad0c-6f435d1e7990', 19, 'Build your own reusable assistant', 'Getting value from AI over time is less about one clever prompt and more about teaching: people have to train a system in what good looks like, explain its output to others, and keep it on track. A custom assistant is that idea made small — you write the instructions once and it behaves that way every time.', 'Human + Machine — Paul R. Daugherty & H. James Wilson (humans as trainers, explainers and sustainers of AI)', '["Pick a task you repeat every week: planning meals, replying to customers, writing posts, studying, reviewing your spending.","Open the feature that saves instructions: a custom GPT or Project in ChatGPT, a Project in Claude, or a Gem in Gemini. If you have none of these, save the instructions as a note to paste in each time.","Write its instructions in four parts. WHO YOU ARE: its role. WHO I AM: your situation, preferences and constraints. HOW TO ANSWER: format, length, tone. RULES: what it must always do and never do, including “ask me a question if anything is unclear.”","Add knowledge: upload or paste two or three reference items, such as your past examples, your price list or your notes.","Test it with three real requests. After each one, improve the instructions instead of just correcting the answer.","Name it and pin it where you will find it next week."]'::jsonb, 'What does your assistant do, and what rule did you have to add after testing it?', 0, false, '[]'::jsonb),
  ('b9e48da4-691f-5012-ad0c-6f435d1e7990', 20, 'Give an AI agent a multi-step job', 'The next stage of AI is not systems that talk, but systems that can be given a goal and carry out the steps to reach it with little supervision. That is more useful and more risky at the same time, because an agent acts, not just answers. The skill to practise is delegation with limits: a clear goal, clear boundaries and a check before anything irreversible happens.', 'The Coming Wave — Mustafa Suleyman (on increasingly capable, goal-directed AI)', '["Choose a job with several steps and low stakes: plan a weekend trip with real options and prices, find the best three products under a budget, or prepare a briefing on a company before an interview.","Use an agent-style feature: Deep Research or Agent mode in ChatGPT, Research in Claude, or Deep Research in Gemini. These browse and work for several minutes on their own.","Write the brief like a manager: “GOAL: [the result]. STEPS I EXPECT: [search, compare, verify, summarise]. LIMITS: only use information from the last 12 months, do not buy or book anything, do not sign up for anything. OUTPUT: a table with links, then your recommendation and what you are unsure about.”","Let it run. Watch what it does: which sites it opens, where it gets stuck, what it skips.","Review the result like a manager, too: open three links, check two facts, and send it back once with corrections.","Write your own rule for agents: what you will let one do alone, and what always needs your approval first (spending money, sending messages, deleting anything)."]'::jsonb, 'What job did you give the agent, and what is your rule about what it may never do without asking you?', 0, false, '[]'::jsonb),
  ('b9e48da4-691f-5012-ad0c-6f435d1e7990', 21, 'Write your personal AI playbook', 'Four habits carry you through whatever comes next: bring AI to everything you do, stay the human in the loop, tell it who to be, and remember that today''s tools are the worst you will ever use. Tools will change and prompts will age, but those habits will not. Three weeks of practice means you can now write your own rules instead of borrowing someone else''s.', 'Co-Intelligence — Ethan Mollick (the four principles of working with AI)', '["Open a new note called “My AI playbook”.","Write section one, WHAT I USE IT FOR: your five best uses from this course, each with the prompt that worked.","Write section two, WHAT I ALWAYS CHECK: facts, numbers, quotes, anything with money or health attached.","Write section three, WHAT STAYS HUMAN: the decisions, relationships and private information you will not hand over.","Set up one weekly routine and put it in your calendar now, for example: every Sunday, ask your custom assistant to plan the week from your to-do list.","Ask the AI to review it: “Here is my AI playbook. What is missing, and what is one advanced skill I should learn next?” Then pick that skill as your next step."]'::jsonb, 'What are the three rules in your playbook, and which weekly routine did you put in your calendar?', 0, false, '[]'::jsonb),
  ('ee91d74f-807f-5be5-a70a-95e266c4bbc9', 1, 'Take a 10-minute walk', 'Staying able to move well for decades matters more than any short burst of fitness, and regular easy movement is the base that makes it possible. The best exercise is the one you''ll still be doing next year. Starting small is not a compromise — it''s the strategy.', 'Outlive — Peter Attia', '["Not medical advice — check with a doctor before starting new exercise.","Walk for 10 minutes today at a comfortable pace. Outside if you can.","Leave your headphones off for the first two minutes and just notice how you feel.","Pick the time you''ll walk tomorrow."]'::jsonb, 'When did you walk, how did you feel afterwards, and what time will you walk tomorrow?', 0, true, '[]'::jsonb),
  ('ee91d74f-807f-5be5-a70a-95e266c4bbc9', 2, 'Set a fixed wake-up time', 'Sleep works best on a regular rhythm. Waking at the same time every day — weekends included — anchors your body clock more than almost anything else you can do. Consistency matters more than any single long night.', 'Why We Sleep — Matthew Walker', '["Choose one wake-up time you can keep all seven days.","Set a repeating alarm for it now.","Count back 8 hours: that is your target time to be in bed.","Take today''s 10-minute walk."]'::jsonb, 'What wake-up time did you choose, and what will you change tonight to make it easier?', 0, true, '[]'::jsonb),
  ('ee91d74f-807f-5be5-a70a-95e266c4bbc9', 3, 'Attach your walk to something you already do', 'New habits stick best when they are stacked onto ones you already have. Instead of relying on motivation, give the habit a fixed place in your day. The clearer the trigger, the less you have to decide.', 'Atomic Habits — James Clear (habit stacking)', '["Pick a daily anchor: after lunch, after work, after dinner.","Say it out loud: ''After I [anchor], I walk for 10 minutes.''","Put your shoes where you will see them at that time.","Do today''s walk at that moment."]'::jsonb, 'What is your anchor, and did the walk feel easier when it had a fixed place in your day?', 0, true, '[]'::jsonb),
  ('ee91d74f-807f-5be5-a70a-95e266c4bbc9', 4, 'Try the sit-and-rise test', 'Being able to lower yourself to the floor and stand back up without using your hands is a simple window into your hip mobility, leg strength and balance. It is not a pass-or-fail exam; it is a baseline you can improve. The fix is mostly spending more time on the floor.', 'Built to Move — Kelly Starrett & Juliet Starrett', '["Stand on a soft surface with a chair nearby for safety.","Cross one foot in front of the other, lower yourself to sitting cross-legged, then stand back up.","Use as little support as you can: note every hand or knee you needed.","Do not force it. If it hurts, stop and simply note where you are today.","Take your 10-minute walk."]'::jsonb, 'How did the sit-and-rise go — how many supports did you need, and what felt stiff?', 0, false, '[]'::jsonb),
  ('ee91d74f-807f-5be5-a70a-95e266c4bbc9', 5, 'Count your steps for a full day', 'Humans are built to walk a great deal, and most of us now walk far less than our bodies expect. Around eight thousand steps or more a day is a practical target, but you cannot improve a number you have never seen. Today you only measure.', 'Built to Move — Kelly Starrett & Juliet Starrett', '["Use your phone''s health app or any step counter.","Carry it all day and live exactly as usual.","Before bed, write down the total.","Add 1,000 to that number. That is your target for the rest of this week."]'::jsonb, 'How many steps did you take today, and what is your new daily target?', 0, false, '[]'::jsonb),
  ('ee91d74f-807f-5be5-a70a-95e266c4bbc9', 6, 'Walk at a conversational pace for 15 minutes', 'The foundation of fitness is easy, steady effort: a pace where you could hold a conversation but would rather not sing. Time spent there trains your body to produce energy efficiently, and it is the kind of exercise you can keep up for life. Going harder is not better for this purpose.', 'Outlive — Peter Attia (zone 2 training)', '["Walk for 15 minutes today.","Find the pace where you can speak in full sentences but notice your breathing.","If you are gasping, slow down. If you could sing, speed up slightly.","Stay at that pace the whole time."]'::jsonb, 'What did conversational pace feel like for you, and was it faster or slower than you expected?', 0, false, '[]'::jsonb),
  ('ee91d74f-807f-5be5-a70a-95e266c4bbc9', 7, 'Spend 15 minutes on the floor', 'Chairs hold your hips in one position for hours, and joints lose the ranges they never use. Sitting on the floor makes you shift, cross your legs, kneel and change position — which is exactly the variety your hips need. It counts while you watch television.', 'Built to Move — Kelly Starrett & Juliet Starrett', '["Tonight, sit on the floor instead of the sofa for 15 minutes.","Change position whenever you feel like it: cross-legged, legs out straight, kneeling, one knee up.","Lean against the sofa if you need back support.","Get up without using your hands if you can.","Keep your walk and your step target."]'::jsonb, 'Which floor positions were comfortable, and which showed you where you are tight?', 0, false, '[]'::jsonb),
  ('ee91d74f-807f-5be5-a70a-95e266c4bbc9', 8, 'Walk before your hardest thinking', 'Exercise is not only for the body. Moving raises the level of chemicals that help brain cells grow and connect, and it sharpens attention and mood for the hours afterwards. A walk before demanding mental work is preparation, not a break from it.', 'Spark — John J. Ratey', '["Look at today and find your most mentally demanding task.","Walk briskly for 10–15 minutes immediately before it.","Start the task as soon as you are back.","Notice your focus and mood for the first 30 minutes."]'::jsonb, 'What did you work on after your walk, and how was your focus compared with a normal day?', 0, false, '[]'::jsonb),
  ('ee91d74f-807f-5be5-a70a-95e266c4bbc9', 9, 'Breathe through your nose while you walk', 'The nose is built for breathing: it filters, warms and moistens air and slows it down. Many of us slip into breathing through the mouth without noticing, especially when moving. Keeping the mouth closed during easy exercise is a simple change that the body adapts to with practice.', 'Breath — James Nestor', '["On today''s walk, keep your lips gently closed.","Breathe in and out through your nose only.","If you feel short of air, slow your pace instead of opening your mouth.","Keep it up for at least 10 minutes.","If your nose is blocked or it feels uncomfortable, stop and breathe normally."]'::jsonb, 'How did nose-only breathing change your walk, and how long could you keep it up?', 0, false, '[]'::jsonb),
  ('ee91d74f-807f-5be5-a70a-95e266c4bbc9', 10, 'Open your hips with a couch stretch', 'Hours of sitting keep the front of the hip shortened, so the leg loses its ability to extend behind you — the motion every walking step depends on. A few minutes of gentle hip-opening each day gives that range back. Slow breathing is what tells the muscle it is safe to let go.', 'Built to Move — Kelly Starrett & Juliet Starrett (hip extension)', '["Kneel in front of a sofa or chair, facing away from it. Place one shin up against the seat, with the other foot forward on the floor.","Easier version: a simple kneeling lunge on a cushion, back knee on the floor.","Keep your body upright and gently squeeze the buttock of the back leg.","Breathe slowly for one minute, then switch sides.","It should feel like a stretch at the front of the hip, never sharp pain. Ease off if it does."]'::jsonb, 'Which hip was tighter, and how did walking feel afterwards?', 0, false, '[]'::jsonb),
  ('ee91d74f-807f-5be5-a70a-95e266c4bbc9', 11, 'Write your list for age 80', 'Instead of exercising with a vague wish to be healthy, decide what you want to be physically able to do in the last decade of your life, and train for those things now. Strength and stamina decline with age, so you need to start well above the level you want to end at. A specific list turns exercise into preparation.', 'Outlive — Peter Attia (the Centenarian Decathlon)', '["Write the things you want to be able to do in your eighties: carry groceries, climb stairs, get up off the floor, lift a grandchild, travel, walk for an hour.","Aim for five to ten items. Be specific.","Next to each, write what you can do today that relates to it.","Circle the one you are furthest from.","Take your walk."]'::jsonb, 'What is on your list for age 80, and which item are you furthest from today?', 0, false, '[]'::jsonb),
  ('ee91d74f-807f-5be5-a70a-95e266c4bbc9', 12, 'Break up your sitting', 'It is not only the total time you sit that matters, but how long you stay still without a break. Standing up and moving for a couple of minutes every half hour wakes up circulation and keeps joints from stiffening. No workout is needed — only frequent small interruptions.', 'Built to Move — Kelly Starrett & Juliet Starrett', '["Set a repeating timer for every 30 minutes during your sitting hours.","Each time it sounds, stand up and move for two minutes: walk, stretch, refill your water.","Take at least one phone call or meeting standing.","Count how many breaks you managed."]'::jsonb, 'How many movement breaks did you take, and how did your body feel by evening?', 0, false, '[]'::jsonb),
  ('ee91d74f-807f-5be5-a70a-95e266c4bbc9', 13, 'Balance on one leg', 'Balance fades quietly with age unless it is practised, and falls are one of the biggest threats to staying independent. The good news is that it responds quickly to small daily doses. Standing on one leg during something you already do every day is enough to start.', 'Built to Move — Kelly Starrett & Juliet Starrett', '["Stand next to a counter or wall you can touch if needed.","Balance on one leg while you brush your teeth: one minute per side.","Too easy? Try it with your eyes closed for a few seconds, staying near support.","Note which side is steadier.","Keep your walk and your step target."]'::jsonb, 'How long could you balance on each leg, and which side was steadier?', 0, false, '[]'::jsonb),
  ('ee91d74f-807f-5be5-a70a-95e266c4bbc9', 14, 'Take a 30-minute walk and review two weeks', 'Of everything you can do for a long, healthy life, regular exercise has the largest effect — bigger than any diet detail or supplement. You do not need intensity to earn most of that benefit; you need to keep turning up. Two weeks in, the aim is to make this normal.', 'Outlive — Peter Attia', '["Walk for 30 minutes today at conversational pace.","Afterwards, look back: how many of the 14 days did you walk?","Write what made it easy on the good days and what got in the way on the others.","Fix one obstacle for next week."]'::jsonb, 'How many of the 14 days did you walk, and what one obstacle will you remove next week?', 0, false, '[]'::jsonb),
  ('ee91d74f-807f-5be5-a70a-95e266c4bbc9', 15, 'Set a caffeine cut-off', 'Caffeine lingers far longer than its buzz: hours after a cup, a large share of it is still active in your system. It works by masking the sleep pressure your brain builds up during the day. An afternoon coffee can thin out your deep sleep even if you fall asleep without trouble.', 'Why We Sleep — Matthew Walker', '["Write down every caffeinated drink you had yesterday, with times: coffee, tea, cola, energy drinks.","Set a cut-off time at least eight hours before your bedtime.","Today, have nothing with caffeine after that time.","Notice how sleepy you feel at bedtime."]'::jsonb, 'What is your caffeine cut-off time, and how did you feel at bedtime without the late cup?', 0, false, '[]'::jsonb),
  ('ee91d74f-807f-5be5-a70a-95e266c4bbc9', 16, 'Make your bedroom dark and cool', 'Your body needs to drop its core temperature to fall asleep and stay asleep, and darkness is the signal that releases the hormone which starts the process. A warm, bright room works against both. A bedroom that is cooler and darker than feels necessary is one of the easiest changes with the biggest return.', 'Why We Sleep — Matthew Walker', '["Tonight, make the room as dark as you can: cover or turn away any lights and standby LEDs.","Lower the temperature. Cool, around 18°C (65°F), suits most people.","Dim the lights in your home for the last hour before bed.","Keep your fixed wake-up time tomorrow."]'::jsonb, 'What did you change in your bedroom, and how did you sleep?', 0, false, '[]'::jsonb),
  ('ee91d74f-807f-5be5-a70a-95e266c4bbc9', 17, 'Get daylight in the morning', 'Daylight is the main signal that sets your body clock. Bright natural light early in the day tells your brain it is daytime, which makes you more alert now and readier for sleep at night. Indoor lighting is far too weak to do the same job.', 'Why We Sleep — Matthew Walker', '["Within an hour of waking, go outside for at least 15–30 minutes.","Combine it with your walk.","No sunglasses if it is comfortable; never look directly at the sun.","On a cloudy day it still counts."]'::jsonb, 'When did you get your morning daylight, and did you notice any difference in your energy?', 0, false, '[]'::jsonb),
  ('ee91d74f-807f-5be5-a70a-95e266c4bbc9', 18, 'Wind down for one hour', 'Sleep is not a switch you flip; the brain needs time to shift down. Bright screens in the evening delay the hormone that signals night, and work or news keeps the mind alert. An hour of low light and quiet activity before bed makes falling asleep much easier.', 'Why We Sleep — Matthew Walker', '["Set an alarm for one hour before bedtime. It means: screens off.","Put your phone to charge outside the bedroom.","Spend the hour on something calm: reading a paper book, stretching, a warm bath or shower, talking.","Keep the lights low."]'::jsonb, 'What did you do in your wind-down hour, and how quickly did you fall asleep?', 0, false, '[]'::jsonb),
  ('ee91d74f-807f-5be5-a70a-95e266c4bbc9', 19, 'Notice what alcohol and late meals do', 'Alcohol sedates, but sedation is not sleep: it breaks the night into fragments you do not remember and suppresses dreaming sleep. A heavy meal late in the evening can also disturb the night. Often the most useful step is simply seeing the connection for yourself.', 'Why We Sleep — Matthew Walker', '["Think back over the last week: which nights did you drink alcohol or eat a large meal close to bedtime?","Compare how you felt the mornings after with the other mornings.","Tonight, finish eating at least two to three hours before bed and skip alcohol.","Write down how you feel tomorrow morning."]'::jsonb, 'What link did you notice between late eating or drinking and how you feel in the morning?', 0, false, '[]'::jsonb),
  ('ee91d74f-807f-5be5-a70a-95e266c4bbc9', 20, 'Don''t lie awake in bed', 'If you lie in bed awake for long, your brain starts to associate the bed with being awake and frustrated. It is better to get up, do something quiet in dim light and return only when sleepy. The bed should mean one thing: sleep.', 'Why We Sleep — Matthew Walker', '["Make a plan for the next time you cannot sleep.","If you have been awake for about 20 minutes, get up.","Go to another room and do something calm in low light: read, stretch gently. No screens.","Go back to bed only when you feel sleepy.","Put a book and a dim light where you will need them tonight."]'::jsonb, 'What is your plan for a sleepless night, and where will you go when you get up?', 0, false, '[]'::jsonb),
  ('ee91d74f-807f-5be5-a70a-95e266c4bbc9', 21, 'Give yourself an eight-hour sleep opportunity', 'Most adults need between seven and nine hours of sleep, and you cannot get eight hours of sleep from seven hours in bed. Regularly sleeping less affects mood, appetite, learning and the immune system. Protecting the time in bed is a decision you make in the evening, not the morning.', 'Why We Sleep — Matthew Walker', '["Count back eight and a half hours from your fixed wake-up time. That is tonight''s lights-out.","Set a bedtime alarm 45 minutes before it.","Look at what usually pushes your bedtime later, and cancel or move one of those things.","Keep it for the next seven nights."]'::jsonb, 'What is your lights-out time, and what did you give up to protect it?', 0, false, '[]'::jsonb),
  ('ee91d74f-807f-5be5-a70a-95e266c4bbc9', 22, 'Eat food your great-grandmother would recognise', 'Much of what fills a modern supermarket is not food so much as edible products engineered in a factory. A simple test cuts through the confusion: would your great-grandmother recognise it as food? Eating mostly real, whole foods makes most nutrition debates unnecessary.', 'In Defense of Food — Michael Pollan', '["Look at everything you eat today.","For each item, ask: would my great-grandmother know what this is?","Count how many items pass and how many do not.","Swap one that fails for a whole-food version tomorrow."]'::jsonb, 'How many of today''s foods passed the great-grandmother test, and what will you swap tomorrow?', 0, false, '[]'::jsonb),
  ('ee91d74f-807f-5be5-a70a-95e266c4bbc9', 23, 'Add a plant to every meal', 'Diets built mostly around plants — vegetables, fruit, beans, whole grains — are consistently linked with better health. It is easier to add than to subtract: putting more plants on the plate crowds out other things without any rule about what to avoid. Weight in vegetables and fruit is a simple thing to count.', 'In Defense of Food — Michael Pollan · Built to Move — Kelly Starrett & Juliet Starrett', '["Add one vegetable or fruit to each meal today, including breakfast.","Aim for variety of colour across the day.","Fresh, frozen and tinned all count.","Tonight, count how many different plants you ate."]'::jsonb, 'How many different plants did you eat today, and which addition was easiest?', 0, false, '[]'::jsonb),
  ('ee91d74f-807f-5be5-a70a-95e266c4bbc9', 24, 'Put protein on your breakfast plate', 'Muscle is one of the best protections you have as you age, and it needs both use and enough protein to be maintained. Many people eat most of their protein at dinner and almost none in the morning. Spreading it across the day, starting with breakfast, supports strength and keeps you full for longer.', 'Outlive — Peter Attia', '["Look at what you normally eat for breakfast.","Add a palm-sized portion of protein: eggs, yoghurt, cottage cheese, beans, tofu, fish or leftovers.","Notice how hungry you are by mid-morning.","Plan tomorrow''s breakfast tonight."]'::jsonb, 'What protein did you add to breakfast, and how did your mid-morning hunger compare?', 0, false, '[]'::jsonb),
  ('ee91d74f-807f-5be5-a70a-95e266c4bbc9', 25, 'Eat slowly and stop before you are full', 'It takes time for fullness to register, so fast eaters finish before the signal arrives. In some of the longest-lived cultures people stop eating when they are about four-fifths full. Slowing down is the simplest way to eat less without counting anything.', 'In Defense of Food — Michael Pollan (not too much)', '["At one meal today, put your fork down between bites.","Take at least 20 minutes over the meal.","Halfway through, pause and ask how hungry you still are.","Stop when you are satisfied, not stuffed. Leave food on the plate if you need to."]'::jsonb, 'How long did the meal take, and at what point did you notice you''d had enough?', 0, false, '[]'::jsonb),
  ('ee91d74f-807f-5be5-a70a-95e266c4bbc9', 26, 'Eat at a table', 'How we eat matters as well as what we eat. Meals taken at a table, without a screen, are eaten more slowly and enjoyed more; food eaten at a desk or in front of a television barely registers. Treating eating as an event is an old rule that protects against mindless snacking.', 'In Defense of Food — Michael Pollan', '["Eat every meal today sitting at a table.","No phone, television or laptop while you eat.","If you can, share one of the meals with someone.","Nothing eaten standing, walking or in the car."]'::jsonb, 'How was eating without a screen, and what did you notice about the food?', 0, false, '[]'::jsonb),
  ('ee91d74f-807f-5be5-a70a-95e266c4bbc9', 27, 'Slow your breathing before bed', 'Slow, even breathing — around five to six breaths a minute — calms the nervous system and steadies the heart. Most of us breathe faster and shallower than we need to. A few minutes of slow breathing through the nose is a simple way to tell the body the day is over.', 'Breath — James Nestor', '["Tonight, sit or lie comfortably before bed.","Breathe in through your nose for about five seconds.","Breathe out through your nose for about five seconds.","Continue for five minutes. Keep it gentle, with no straining or holding.","If you feel light-headed, stop and breathe normally."]'::jsonb, 'How did you feel after five minutes of slow breathing, and did it change how you fell asleep?', 0, false, '[]'::jsonb),
  ('ee91d74f-807f-5be5-a70a-95e266c4bbc9', 28, 'Shop the edges of the store', 'In most supermarkets the fresh food sits around the outside walls and the heavily processed products fill the middle aisles. A long list of ingredients you cannot pronounce is a sign that something has moved a long way from food. Changing what comes home changes what gets eaten.', 'In Defense of Food — Michael Pollan', '["On your next shop, fill the trolley from the outer edges first: vegetables, fruit, eggs, fish, meat, dairy.","For anything packaged, read the ingredient list.","Put back one item with more than five ingredients, or ingredients you would not keep in a kitchen.","No shopping today? Check three packaged items in your cupboard the same way."]'::jsonb, 'What did you put back or notice on the labels, and what did you buy instead?', 0, false, '[]'::jsonb),
  ('ee91d74f-807f-5be5-a70a-95e266c4bbc9', 29, 'Stand up from a chair five times', 'Strength is one of the strongest predictors of how well and how long people live, and the muscles of the legs matter most for staying independent. Standing up from a chair is a squat — the movement you need for the rest of your life. Slow and controlled beats fast and many.', 'Outlive — Peter Attia', '["Not medical advice — check with a doctor before starting new exercise.","Sit on a firm chair, feet flat and hip-width apart.","Stand up without using your hands. Cross your arms over your chest.","Lower yourself slowly, taking three seconds to sit.","Do five. Rest a minute and do five more.","Use your hands or a higher seat if you need to. Stop if anything hurts."]'::jsonb, 'How did five slow sit-to-stands feel, and did you need your hands?', 0, false, '[]'::jsonb),
  ('ee91d74f-807f-5be5-a70a-95e266c4bbc9', 30, 'Hold a deep squat with support', 'Resting in a deep squat is a position humans used for most of history and many adults have lost. Getting it back restores movement in the hips, knees and ankles together. Holding on to something lets you relax into it safely.', 'Built to Move — Kelly Starrett & Juliet Starrett', '["Hold a door frame, a sturdy table or a kitchen counter with both hands.","Lower yourself as far as is comfortable, heels on the floor if possible.","Stay there for five slow breaths, using your hands to take as much weight as you need.","Stand up and repeat three times.","Go only as deep as is pain-free. A cushion under the heels can help."]'::jsonb, 'How deep could you squat with support, and where did you feel the limit?', 0, false, '[]'::jsonb),
  ('ee91d74f-807f-5be5-a70a-95e266c4bbc9', 31, 'Carry something heavy', 'Grip strength is closely tied to overall strength and to how well people age, and carrying a load is one of the most natural ways to build it. It trains the hands, shoulders, trunk and legs at once. You already own the equipment: bags.', 'Outlive — Peter Attia (grip strength and carries)', '["Fill two bags with equal weight: groceries, books or water bottles. Start light.","Stand tall, shoulders down and back.","Walk with one bag in each hand for 30–60 seconds.","Rest and repeat three times.","Put the bags down by bending your knees, not rounding your back."]'::jsonb, 'What did you carry, for how long, and what tired first — hands, shoulders or legs?', 0, false, '[]'::jsonb),
  ('ee91d74f-807f-5be5-a70a-95e266c4bbc9', 32, 'Do push-ups against a wall or counter', 'Muscle is lost steadily with age unless it is asked to work, and the upper body is often neglected. Pushing your own weight is enough to begin, and changing the angle lets anyone find a level that is hard but possible. The right version is the one you can do with good form.', 'Outlive — Peter Attia', '["Stand facing a wall or a sturdy kitchen counter, hands on it at shoulder width.","Keep your body in a straight line from head to heels.","Bend your elbows to bring your chest towards the surface, then push back.","Do two sets of 8–10.","Too easy? Use a lower surface. Too hard? Stand closer to the wall."]'::jsonb, 'Which version did you use, and how many could you do with good form?', 0, false, '[]'::jsonb),
  ('ee91d74f-807f-5be5-a70a-95e266c4bbc9', 33, 'Wake up your feet', 'Before strength comes stability: the ability to control your body and pass force safely through it. That starts with the feet, your only contact with the ground, which spend most of their lives asleep inside shoes. Learning to move your toes on purpose is the first step in training balance.', 'Outlive — Peter Attia (stability)', '["Take off your shoes and socks. Stand or sit with feet flat.","Lift only your big toes, keeping the others down. Then reverse: big toes down, others up.","Spread all your toes as wide as you can and hold for five seconds.","Repeat each ten times.","Finish by balancing on one leg, barefoot, for 30 seconds each side."]'::jsonb, 'How much control did you have over your toes, and which movement was hardest?', 0, false, '[]'::jsonb),
  ('ee91d74f-807f-5be5-a70a-95e266c4bbc9', 34, 'Bridge your hips', 'The muscles at the back of the hips drive walking, climbing and getting up, and long hours of sitting switch them off. Learning to extend the hip using the buttocks instead of the lower back protects the spine in everything else you do. A bridge on the floor teaches it safely.', 'Outlive — Peter Attia · Built to Move — Kelly Starrett & Juliet Starrett', '["Lie on your back, knees bent, feet flat and hip-width apart.","Press through your heels and lift your hips until your body is straight from shoulders to knees.","Squeeze your buttocks at the top for two seconds. Do not arch your lower back.","Lower slowly. Do two sets of 10.","If your back or hamstrings cramp, lower the height and move your feet closer."]'::jsonb, 'Where did you feel the bridge working, and how many could you do?', 0, false, '[]'::jsonb),
  ('ee91d74f-807f-5be5-a70a-95e266c4bbc9', 35, 'Step up and step down slowly', 'Going down is harder on the body than going up: lowering yourself under control is the strength that prevents falls on stairs and kerbs. It is also the first kind of strength to fade. Practising a slow descent is one of the most useful things you can train.', 'Outlive — Peter Attia (eccentric strength)', '["Use the bottom step of a staircase and hold the rail.","Step up with your right foot, bring the left up to join it.","Step down with the left foot, taking three full seconds to lower.","Do eight, then switch legs.","Use a lower step if your knee complains. Stop if there is pain."]'::jsonb, 'How controlled was your step-down, and was one leg weaker than the other?', 0, false, '[]'::jsonb),
  ('ee91d74f-807f-5be5-a70a-95e266c4bbc9', 36, 'Practise getting up from the floor', 'Being able to get down to the floor and back up is the difference between a stumble being an event and being an emergency. It uses the whole body and it can be trained like any other skill. Repeat the test from the first week and see what a month has changed.', 'Built to Move — Kelly Starrett & Juliet Starrett · Outlive — Peter Attia', '["Repeat the Day 4 sit-and-rise test, with a chair nearby.","Note how many supports you needed and compare with Day 4.","Then practise five times, using whatever help you need: go down to sitting, come back up.","Try a different route each time: via one knee, via both knees, rolling to the side."]'::jsonb, 'How did today''s sit-and-rise compare with Day 4, and which way of getting up was easiest?', 0, false, '[]'::jsonb),
  ('ee91d74f-807f-5be5-a70a-95e266c4bbc9', 37, 'Breathe into your whole trunk', 'Good breathing is the base of a stable body: when the air expands the ribs, sides and back together, it creates the pressure that supports the spine from the inside. Many people breathe only into the upper chest. Relearning it lying down makes every other exercise safer.', 'Outlive — Peter Attia (stability)', '["Lie on your back with your knees bent.","Put one hand on your belly and one on the side of your lower ribs.","Breathe in through your nose so that your belly, sides and lower back all expand, like a cylinder filling.","Breathe out slowly and feel everything gently draw in.","Do ten slow breaths, then do five sit-to-stands using the same breath."]'::jsonb, 'Where did your breath go at first, and could you get your sides and back to expand?', 0, false, '[]'::jsonb),
  ('ee91d74f-807f-5be5-a70a-95e266c4bbc9', 38, 'Stack a five-minute routine onto your day', 'A behaviour becomes a habit when it has a fixed cue and is small enough to do even on a bad day. Linking a short strength routine to something you already do removes the decision. Five minutes done daily builds more than an hour done occasionally.', 'Atomic Habits — James Clear (habit stacking; the two-minute rule)', '["Choose three movements from this week: for example sit-to-stand, wall push-up, hip bridge.","Pick a daily anchor: after brushing your teeth, while the kettle boils, after your walk.","Write it: “After I [anchor], I do 8 sit-to-stands, 8 push-ups and 8 bridges.”","Do it once today, right after the anchor.","Put a tick on a calendar where you will see it."]'::jsonb, 'What is your five-minute routine, and what did you attach it to?', 0, false, '[]'::jsonb),
  ('ee91d74f-807f-5be5-a70a-95e266c4bbc9', 39, 'Walk with a light backpack', 'Carrying weight while you walk is something people did for all of human history. It turns an ordinary walk into strength work for the legs, trunk and back while staying easy on the joints, and it raises your effort without needing to run. Start much lighter than you think you need.', 'Outlive — Peter Attia (rucking)', '["Put something light in a backpack: a couple of books or water bottles, about 2–4 kg to begin.","Tighten the straps so the pack sits high and close to your back.","Walk for 20 minutes at conversational pace.","Stand tall; do not lean forward.","If your back or shoulders hurt, take weight out."]'::jsonb, 'How much did you carry, and how did the walk feel compared with walking unloaded?', 0, false, '[]'::jsonb),
  ('ee91d74f-807f-5be5-a70a-95e266c4bbc9', 40, 'Track your mood before and after', 'Movement changes the brain''s chemistry within minutes: it lifts mood, lowers stress and takes the edge off anxiety. The effect is reliable enough that you can feel it for yourself, and noticing it is what makes exercise something you want instead of something you should do.', 'Spark — John J. Ratey', '["Before today''s walk or routine, rate your mood and stress from 1 to 10.","Do at least 20 minutes of movement.","Rate both again straight afterwards, and once more two hours later.","Write the three sets of numbers down."]'::jsonb, 'What were your mood and stress numbers before and after, and what does that tell you?', 0, false, '[]'::jsonb),
  ('ee91d74f-807f-5be5-a70a-95e266c4bbc9', 41, 'Plan your normal week', 'The last decade of life is shaped by what you do in the decades before it. A simple, repeatable week — easy movement most days, strength a few times, sleep protected — is what carries you there. A plan that fits your real life is worth more than a perfect one you abandon.', 'Outlive — Peter Attia (the Marginal Decade)', '["Open your calendar for a normal week.","Place a walk on at least five days, with times.","Place your strength routine on at least three days.","Write your fixed wake-up time and lights-out time.","Look at your Day 11 list and check that the plan trains for it."]'::jsonb, 'What does your normal week look like now — which days, which times?', 0, false, '[]'::jsonb),
  ('ee91d74f-807f-5be5-a70a-95e266c4bbc9', 42, 'Retest and name who you have become', 'The deepest change is not in what you do but in who you believe you are. Every time you walk, sleep on schedule or do your routine, you cast a vote for being a person who looks after their body. After six weeks you have enough votes to say it out loud.', 'Atomic Habits — James Clear (identity-based habits)', '["Repeat three tests: your daily steps (Day 5), the sit-and-rise (Day 4) and one-leg balance (Day 13).","Write the then-and-now numbers side by side.","Finish this sentence: “I am the kind of person who…”","Choose the three habits from this course you will keep.","Tell one person what you have changed."]'::jsonb, 'How do your numbers compare with week one, and how did you finish “I am the kind of person who…”?', 0, false, '[]'::jsonb),
  ('5b5add39-54a3-50d5-a694-8d7163f93bd1', 1, 'Name your frog', 'The task you''re most likely to put off is usually the one that would make the biggest difference. If you do that one first, the rest of the day gets lighter. Naming it clearly is half the battle — vague tasks are easy to avoid.', 'Eat That Frog! — Brian Tracy', '["Write down the one task you''ve been avoiding the longest.","Write the very first physical step (open the file, find the number, write one line).","Do only that first step today. Stop there if you want."]'::jsonb, 'What is your frog, and what happened when you did the first step?', 0, true, '[]'::jsonb),
  ('5b5add39-54a3-50d5-a694-8d7163f93bd1', 2, 'Count your weeks', 'A human life is short — roughly four thousand weeks. You will never get everything done, and accepting that is freeing: it lets you choose a few things that matter instead of drowning in all of them. Time management starts with admitting the limit.', 'Four Thousand Weeks — Oliver Burkeman', '["Multiply your age by 52. Subtract it from 4,000.","Look at the number for a minute.","Write down three things you''d regret never starting.","Circle the one you would start this week."]'::jsonb, 'What did you circle, and what have you been doing instead of it?', 0, true, '[]'::jsonb),
  ('5b5add39-54a3-50d5-a694-8d7163f93bd1', 3, 'Sort urgent from important', 'Urgent things shout; important things wait quietly. Most of what moves a life forward is important but not urgent, so it gets pushed aside by whatever is loudest. Putting first things first means scheduling the quiet ones on purpose.', 'The 7 Habits of Highly Effective People — Stephen R. Covey (Habit 3: put first things first)', '["List everything on your plate today.","Mark each item: urgent, important, both or neither.","Choose one item that is important but NOT urgent.","Give it 20 minutes today, before the urgent things."]'::jsonb, 'Which important-but-not-urgent thing did you give 20 minutes to, and what got in the way?', 0, false, '[]'::jsonb),
  ('5b5add39-54a3-50d5-a694-8d7163f93bd1', 4, 'Empty your head onto paper', 'Your mind is for having ideas, not for holding them. Every unfinished commitment you keep in your head nags at you at the wrong moments and makes everything feel bigger than it is. Getting all of it into one trusted place outside your head is where calm starts.', 'Getting Things Done — David Allen (capture)', '["Set a timer for 15 minutes.","Write down everything that has your attention: tasks, errands, worries, promises, ideas. One per line.","Do not organise or judge. Keep going until nothing more comes.","Count the items. Keep the list — you will use it all week."]'::jsonb, 'How many items came out of your head, and how did you feel when the list was finished?', 0, false, '[]'::jsonb),
  ('5b5add39-54a3-50d5-a694-8d7163f93bd1', 5, 'Catch yourself procrastinating', 'Procrastination is not laziness; it is a way of coping with the anxiety a task brings up — fear of failing, of being judged, of it not being perfect. You can only change a pattern you can see. Noting when you put something off and what you felt just before shows you what you are really avoiding.', 'The Now Habit — Neil Fiore (the procrastination log)', '["Keep a note open all day.","Each time you put something off, write: the task, the time, what you did instead, and what you were feeling.","Do not try to fix it today. Only notice.","Tonight, look for the pattern: which type of task, which time of day, which feeling."]'::jsonb, 'What pattern did you see — which kind of task do you avoid, and what feeling comes just before?', 0, false, '[]'::jsonb),
  ('5b5add39-54a3-50d5-a694-8d7163f93bd1', 6, 'Begin with the end in mind', 'Everything is created twice: first in the mind, then in reality. If you do not decide what your life is for, the demands of other people will decide it for you, and you can be very busy climbing a ladder that is leaning against the wrong wall. Knowing the end gives every day a direction.', 'The 7 Habits of Highly Effective People — Stephen R. Covey (Habit 2: begin with the end in mind)', '["Imagine your 80th birthday. Four people speak: someone from your family, a friend, someone from your work, someone from your community.","Write one sentence you would want each of them to say about you.","Underline the words that repeat.","Write one thing you did this week that fits those words, and one that does not."]'::jsonb, 'What do you want to be said about you, and what did you do this week that doesn''t fit?', 0, false, '[]'::jsonb),
  ('5b5add39-54a3-50d5-a694-8d7163f93bd1', 7, 'Find your vital 20 percent', 'A small share of what you do produces most of your results. Of ten tasks, two will usually be worth more than the other eight put together — and those two are often the hardest, which is why they get put off. Being busy with the low-value eight feels productive and changes nothing.', 'Eat That Frog! — Brian Tracy (apply the 80/20 rule to everything)', '["Take your list from Day 4.","Pick the ten items most related to your work or main goal.","Ask of each: if this were the only thing I finished this month, how much would it matter?","Star the two with the biggest payoff.","Spend your first 30 working minutes today on one of them."]'::jsonb, 'Which two tasks are your vital 20 percent, and what did 30 minutes on one of them achieve?', 0, false, '[]'::jsonb),
  ('5b5add39-54a3-50d5-a694-8d7163f93bd1', 8, 'Decide what you will fail at', 'Because your time is finite, you are guaranteed to fall short somewhere. The choice is only whether you pick those areas in advance or let them be picked for you by exhaustion. Choosing to do some things badly, on purpose, is what makes it possible to do a few things well.', 'Four Thousand Weeks — Oliver Burkeman (strategic underachievement)', '["List the areas of your life that demand effort right now: work, home, fitness, friends, a side project, and so on.","Choose two that get your best energy for the next month.","Choose two where ''good enough'' is your official standard for now.","Write down what ''good enough'' looks like in each.","Tell one person affected by it, so it is a decision and not a secret."]'::jsonb, 'What are you choosing to be mediocre at this month, and what did that free you to focus on?', 0, false, '[]'::jsonb),
  ('5b5add39-54a3-50d5-a694-8d7163f93bd1', 9, 'Rank your list with ABCDE', 'A list without priorities invites you to do the easiest thing first. Marking each task by the consequence of not doing it — and refusing to start a lower letter while a higher one is unfinished — forces the important work to the front. Thinking on paper for two minutes saves hours of drifting.', 'Eat That Frog! — Brian Tracy (the ABCDE method)', '["Write today''s task list.","Mark each one: A = serious consequences if not done, B = mild consequences, C = nice to do, D = delegate, E = eliminate.","Number the A tasks: A-1, A-2, A-3.","Start A-1 immediately and stay with it until it is finished or you reach a real stopping point.","Cross out every E."]'::jsonb, 'What was your A-1 task, and how far did you get before touching anything else?', 0, false, '[]'::jsonb),
  ('5b5add39-54a3-50d5-a694-8d7163f93bd1', 10, 'Turn projects into next actions', 'You cannot do a project; you can only do the next physical action. Items like ''sort out taxes'' sit on a list for months because they are not actions — they are problems. Deciding the very next visible step turns something you avoid into something you can begin.', 'Getting Things Done — David Allen (the next-action decision)', '["Pick the three items on your list that have been stuck longest.","For each, write the outcome: “This is done when…”","Then write the next physical action, starting with a verb: call, email, open, draft, buy.","Make it small enough to start within two minutes.","Do the next action for one of the three right now."]'::jsonb, 'What were your three stuck items, and what next action did you write for each?', 0, false, '[]'::jsonb),
  ('5b5add39-54a3-50d5-a694-8d7163f93bd1', 11, 'Clear everything that takes two minutes', 'If an action takes less than two minutes, do it the moment you notice it. Storing it, tracking it and remembering it later costs more time than simply finishing it. A surprising share of what weighs on you is made of things this small.', 'Getting Things Done — David Allen (the two-minute rule)', '["Go through your list and mark every item that would take two minutes or less.","Set a timer for 30 minutes.","Do them one after another: the reply, the form, the booking, the payment.","Count how many you cleared.","From now on, do two-minute tasks the moment they appear."]'::jsonb, 'How many two-minute tasks did you clear in half an hour, and which one had been waiting longest?', 0, false, '[]'::jsonb),
  ('5b5add39-54a3-50d5-a694-8d7163f93bd1', 12, 'Slice the task thin', 'A big task is intimidating whole and harmless in slices. You can start by committing to one thin slice, or by working on it for a short fixed time and then stopping. Finishing a piece creates the urge to finish the next one.', 'Eat That Frog! — Brian Tracy (slice and dice the task)', '["Take your biggest unfinished task.","Break it into slices small enough to finish in 10–15 minutes each. Write them as a list.","Do the first slice now.","If you want to continue, do the second. If not, stop — you kept the promise.","Put the next slice in your calendar for tomorrow."]'::jsonb, 'How many slices did your task become, and how many did you finish today?', 0, false, '[]'::jsonb),
  ('5b5add39-54a3-50d5-a694-8d7163f93bd1', 13, 'Say ''I choose to'' and start for 30 minutes', 'The language of pressure — ''I have to'', ''I should'' — makes you feel like a victim and invites rebellion in the form of delay. Replacing it with ''I choose to'' and asking only ''when can I start?'' takes away the dread of finishing. Thirty minutes of real work, followed by a reward you planned in advance, is enough to break the pattern.', 'The Now Habit — Neil Fiore (the language of the producer; the Unschedule)', '["First put something enjoyable in today''s schedule: a walk, a show, time with a friend. It is your guaranteed reward.","Choose the task you are resisting most.","Say out loud: “I choose to start on [task] at [time] for 30 minutes.”","Work for exactly 30 minutes without interruption. You are only starting, not finishing.","Stop, note the 30 minutes as a win, and take the reward without guilt."]'::jsonb, 'What did you choose to start, and how did ''I choose to'' feel compared with ''I have to''?', 0, false, '[]'::jsonb),
  ('5b5add39-54a3-50d5-a694-8d7163f93bd1', 14, 'Ask the focusing question', 'Not everything matters equally. Extraordinary results come from narrowing your focus to the single action that makes the others easier or unnecessary, like the first domino that knocks down the rest. One question, asked honestly, finds it.', 'The ONE Thing — Gary Keller & Jay Papasan', '["Pick your most important goal for the next three months.","Ask: “What is the one thing I can do this week such that, by doing it, everything else becomes easier or unnecessary?”","Ask it again for today.","Block time for that one thing before anything else.","Do it, or at least start it, before you open your messages."]'::jsonb, 'What was your one thing for today, and did you do it before opening your messages?', 0, false, '[]'::jsonb),
  ('5b5add39-54a3-50d5-a694-8d7163f93bd1', 15, 'Plan your week around the big rocks', 'If you fill a jar with sand first, the big rocks will not fit; put the rocks in first and the sand settles around them. A week works the same way. Planning weekly, not daily, lets you place your most important commitments before the small things flood in.', 'The 7 Habits of Highly Effective People — Stephen R. Covey (Habit 3: weekly planning)', '["Write your main roles: for example parent, partner, professional, friend, yourself.","For each role, write one result that would matter this week. These are your big rocks.","Open your calendar and give each big rock a specific day and time.","Only then add everything else around them.","Tonight, check tomorrow''s big rock."]'::jsonb, 'What are your big rocks for this week, and when exactly is each one scheduled?', 0, false, '[]'::jsonb),
  ('5b5add39-54a3-50d5-a694-8d7163f93bd1', 16, 'Say no to something good', 'The undisciplined pursuit of more is why capable people end up stretched thin and making little progress in any direction. The alternative is fewer things done better: if something is not a clear yes, treat it as a no. Every yes to something minor is a no to something that matters.', 'Essentialism — Greg McKeown (the 90 percent rule)', '["List your current commitments and open requests.","Score each from 0 to 100 on how much it matters to you.","Anything under 90 is a candidate to drop, delay or hand over.","Pick one and say no today. Use a clear, kind sentence: “Thank you for thinking of me. I can''t take this on right now.”","Notice what actually happens after you say it."]'::jsonb, 'What did you say no to, and what did it free up?', 0, false, '[]'::jsonb),
  ('5b5add39-54a3-50d5-a694-8d7163f93bd1', 17, 'Give every hour a job', 'A day without a plan gets spent reacting to whatever arrives. Deciding in advance what each block of time is for means you make the decision once, with a clear head, instead of dozens of times while tired. The plan will change — what matters is that you re-plan instead of drifting.', 'Deep Work — Cal Newport (schedule every minute of your day)', '["Take a sheet of paper and write the hours of your working day down the side.","Divide the day into blocks of at least 30 minutes and give each one a job.","Group small tasks into one block. Leave one block empty for overflow.","When something knocks you off the plan, take a minute and redraw the remaining blocks.","Tonight, check how close reality came to the plan."]'::jsonb, 'How closely did your day follow your blocks, and where did it break down?', 0, false, '[]'::jsonb),
  ('5b5add39-54a3-50d5-a694-8d7163f93bd1', 18, 'Do one block of deep work', 'The ability to concentrate without distraction on a demanding task is becoming rare at exactly the moment it is becoming most valuable. An hour of unbroken focus produces more than a morning of interrupted effort, because every switch leaves part of your attention behind. Depth is a skill, and it has to be trained.', 'Deep Work — Cal Newport', '["Choose one demanding task that would really benefit from full attention.","Pick a 60–90 minute slot and a place where you will not be interrupted.","Put your phone in another room. Close email, chat and every unneeded tab.","Write what you intend to produce by the end of the session.","Work until the time is up. If your mind wanders, bring it back — no checking anything."]'::jsonb, 'What did you produce in your deep-work block, and how many times did you want to check your phone?', 0, false, '[]'::jsonb),
  ('5b5add39-54a3-50d5-a694-8d7163f93bd1', 19, 'Let yourself be bored', 'If you reach for your phone at every idle moment, you train your brain to demand novelty — and it will demand it during hard work, too. Concentration is built in the gaps: waiting, walking, standing in line. Tolerating boredom there is what makes focus possible later.', 'Deep Work — Cal Newport (embrace boredom)', '["Choose three everyday gaps today: a queue, a commute, waiting for the kettle, a walk.","During each one, keep your phone in your pocket. No music or podcast either.","Just let your mind wander, or think through one problem.","Notice the urge to reach for the phone. Do not act on it.","Tonight, write what your mind came up with when it was left alone."]'::jsonb, 'What did your mind do during the gaps, and how strong was the pull of the phone?', 0, false, '[]'::jsonb),
  ('5b5add39-54a3-50d5-a694-8d7163f93bd1', 20, 'End your workday with a shutdown ritual', 'Unfinished tasks keep running in the back of your mind all evening unless you have a plan for them that you trust. A short end-of-day routine — check what is open, decide the next step for each, then deliberately stop — lets your brain let go. Rest is not the opposite of good work; it is what makes it possible.', 'Deep Work — Cal Newport (the shutdown ritual)', '["Fifteen minutes before you finish, check your inbox and task list one last time.","For anything unfinished, write down its next step and when you will do it.","Look at tomorrow''s calendar and choose your first task.","Close everything and say a phrase out loud to mark the end, such as “Shutdown complete.”","No work email or work thoughts after that. If one appears, remind yourself it is already captured."]'::jsonb, 'What was your shutdown phrase, and how was your evening different once work was properly closed?', 0, false, '[]'::jsonb),
  ('5b5add39-54a3-50d5-a694-8d7163f93bd1', 21, 'Limit your work in progress to three', 'When everything is started and nothing is finished, each new difficulty tempts you to jump to another project. A hard limit on how many things you allow in progress at once forces you either to finish or to consciously abandon. Nothing new comes in until something goes out.', 'Four Thousand Weeks — Oliver Burkeman (limit your work in progress)', '["List everything you have started and not finished.","Choose three. These are your only active projects.","Move everything else to a ''waiting'' list. It is not cancelled — it is not allowed in yet.","Work only on the three until one is complete.","Only then pull one item in from the waiting list."]'::jsonb, 'Which three projects made the cut, and what was hardest to put on the waiting list?', 0, false, '[]'::jsonb),
  ('5b5add39-54a3-50d5-a694-8d7163f93bd1', 22, 'Batch the shallow work', 'Email, messages and small admin tasks feel like work and fill the whole day if you let them. Confining them to a few fixed windows protects the rest of your time for what actually creates value. If a tool takes more of your attention than it gives back, it does not deserve a place in your day.', 'Deep Work — Cal Newport (drain the shallows)', '["Pick two or three fixed times today for email and messages, for example 11:30 and 16:30.","Outside those windows, close your inbox and turn off notifications.","Deal with every message in one pass when the window opens.","Choose one app that eats your attention and remove it from your phone''s home screen for a week.","At the end of the day, note what you got done in the protected time."]'::jsonb, 'Which windows did you set, and what did you do with the time you protected?', 0, false, '[]'::jsonb),
  ('5b5add39-54a3-50d5-a694-8d7163f93bd1', 23, 'Sharpen the saw', 'Someone sawing with a blunt blade for hours insists they are too busy to stop and sharpen it. You are the tool everything else depends on, and it wears down without regular renewal — of body, mind, relationships and purpose. Looking after yourself is not time taken from the work; it is what keeps the work possible.', 'The 7 Habits of Highly Effective People — Stephen R. Covey (Habit 7: sharpen the saw)', '["Rate your current state from 1 to 10 in four areas: body, mind, relationships, sense of purpose.","Pick the lowest.","Do one 30-minute act of renewal for it today: a walk, a book, a real conversation, quiet time.","Put a repeating weekly slot in your calendar for that area."]'::jsonb, 'Which area scored lowest, and what did you do today to renew it?', 0, false, '[]'::jsonb),
  ('5b5add39-54a3-50d5-a694-8d7163f93bd1', 24, 'Run your first weekly review', 'A system only stays trustworthy if you look at all of it regularly. Once a week, clear your head, check every open commitment and decide what next week is for. That hour is what keeps everything from the last 24 days working instead of fading.', 'Getting Things Done — David Allen (the weekly review)', '["Set aside 45 minutes.","Empty your head again, as on Day 4. Add everything new to your list.","Check each project: is there a next action written down?","Look at the past week: what went well, what you avoided, and why.","Choose next week''s big rocks and schedule them.","Put this review in your calendar as a repeating weekly appointment."]'::jsonb, 'What are next week''s big rocks, and which habit from this course will you keep?', 0, false, '[]'::jsonb),
  ('0cf63e3a-f5f9-5b2f-aa36-0874ae4318cd', 1, 'Go one day without criticising', 'Criticism rarely changes anyone — it puts people on the defensive and makes them justify themselves. People respond far better to being understood than to being corrected. Holding back a complaint is the first people-skill, and the hardest.', 'How to Win Friends and Influence People — Dale Carnegie (Principle 1: don''t criticise, condemn or complain)', '["From now until you sleep: no criticising, condemning or complaining about anyone.","When you catch the urge, pause and ask: ''Why might they have done that?''","Keep a tally of how many times you caught yourself."]'::jsonb, 'How many times did you catch yourself, and what was the hardest moment to stay quiet?', 0, true, '[]'::jsonb),
  ('0cf63e3a-f5f9-5b2f-aa36-0874ae4318cd', 2, 'Give one honest, specific compliment', 'Almost everyone is hungry to feel appreciated, and sincere appreciation is different from flattery because it is specific and true. Noticing what someone did well — and saying it — costs nothing and is remembered for a long time.', 'How to Win Friends and Influence People — Dale Carnegie (Principle 2: give honest and sincere appreciation)', '["Pick one person you''ll see or message today.","Find something they genuinely did well. Be specific.","Tell them, without asking for anything afterwards."]'::jsonb, 'Who did you appreciate, what exactly did you say, and how did they react?', 0, true, '[]'::jsonb),
  ('0cf63e3a-f5f9-5b2f-aa36-0874ae4318cd', 3, 'Talk about what they want', 'The only way to influence someone is to talk about what they want and show them how to get it. People act for their own reasons, not yours, so a request framed around your needs is easy to ignore. Before you ask, work out why it would be good for them. An appeal to someone''s own interest succeeds where an appeal to gratitude fails.', 'How to Win Friends and Influence People — Dale Carnegie (Principle 3: arouse in the other person an eager want) · The 48 Laws of Power — Robert Greene (Law 13)', '["Think of one thing you need from someone today.","Before asking, write down what that person wants or worries about.","Rewrite your request so it starts with their benefit, not yours.","Make the request and notice the difference in how it lands."]'::jsonb, 'What did you ask for, and how did you frame it around what the other person wanted?', 0, true, '[]'::jsonb),
  ('0cf63e3a-f5f9-5b2f-aa36-0874ae4318cd', 4, 'Be interested instead of interesting', 'You make more friends in two months by being genuinely interested in other people than in two years of trying to get them interested in you. Curiosity about someone''s life is rare enough that people remember who showed it. Interest cannot be faked for long — it has to be real.', 'How to Win Friends and Influence People — Dale Carnegie (Principle 4: become genuinely interested in other people)', '["Choose one person you usually only exchange small talk with.","Ask a question about something they care about: their work, family, a project, a hobby.","Ask one follow-up question based on their answer.","Say nothing about yourself unless they ask."]'::jsonb, 'Who did you get curious about, and what did you learn that you didn''t know before?', 0, false, '[]'::jsonb),
  ('0cf63e3a-f5f9-5b2f-aa36-0874ae4318cd', 5, 'Smile first', 'Actions speak louder than words, and a smile says: I like you, I am glad to see you. It costs nothing and changes how the next thirty seconds of any meeting go. A forced grin fools nobody — think of something you are actually glad about, and it becomes real.', 'How to Win Friends and Influence People — Dale Carnegie (Principle 5: smile)', '["Before each conversation today, think of one thing you are glad about.","Smile at the first five people you meet or speak to — including on the phone, where it can be heard.","Watch what their face does in return.","Smile at one stranger: a cashier, a neighbour, a driver."]'::jsonb, 'How did people respond when you smiled first, and which reaction surprised you?', 0, false, '[]'::jsonb),
  ('0cf63e3a-f5f9-5b2f-aa36-0874ae4318cd', 6, 'Use people''s names', 'A person''s name is, to that person, the sweetest and most important sound in any language. Remembering it and using it is a small compliment that most people never bother to pay. Forgetting it, or getting it wrong, tells them they did not matter enough.', 'How to Win Friends and Influence People — Dale Carnegie (Principle 6: remember that a person''s name is the sweetest sound)', '["Learn the name of one person you see regularly but have never addressed by name.","When you hear a new name today, repeat it straight away: “Nice to meet you, [name].”","Use each person''s name once at the start and once at the end of a conversation.","Write new names down tonight with one detail about the person."]'::jsonb, 'Whose name did you learn or use today, and how did they react when you used it?', 0, false, '[]'::jsonb),
  ('0cf63e3a-f5f9-5b2f-aa36-0874ae4318cd', 7, 'Listen for two full minutes', 'To be a good conversationalist, be a good listener. Most people are so busy planning what to say next that they never really hear the other person — and everyone can feel the difference. Giving someone your complete attention is one of the highest compliments you can pay. Saying less than necessary also means you learn more than you give away.', 'How to Win Friends and Influence People — Dale Carnegie (Principle 7: be a good listener; encourage others to talk about themselves) · The 48 Laws of Power — Robert Greene (Law 4)', '["In one conversation today, ask an open question and then stay quiet.","Listen for two full minutes without interrupting, advising or switching to your own story.","Show you are following: nod, and say “go on” or “what happened then?”","Summarise what they said in one sentence before you add anything of your own."]'::jsonb, 'Who did you listen to, and what did you hear that you would normally have talked over?', 0, false, '[]'::jsonb),
  ('0cf63e3a-f5f9-5b2f-aa36-0874ae4318cd', 8, 'Talk about their interests', 'The royal road to a person''s heart is to talk about the things they treasure most. A few minutes spent finding out what someone cares about before you meet them changes the whole conversation. People light up when the subject is theirs.', 'How to Win Friends and Influence People — Dale Carnegie (Principle 8: talk in terms of the other person''s interests)', '["Pick someone you will speak with today.","Before you do, find out or recall one thing they love: a team, a hobby, their children, a place.","Bring it up early and let them talk.","Notice how their energy changes when the topic is theirs."]'::jsonb, 'What interest did you bring up, and how did the person change when you did?', 0, false, '[]'::jsonb),
  ('0cf63e3a-f5f9-5b2f-aa36-0874ae4318cd', 9, 'Make someone feel important', 'Almost everyone you meet feels superior to you in some way, and the sure way to their heart is to let them know, sincerely, that you recognise it. The wish to feel important is one of the deepest human hungers. Do it sincerely or not at all.', 'How to Win Friends and Influence People — Dale Carnegie (Principle 9: make the other person feel important — and do it sincerely)', '["Choose someone whose work usually goes unnoticed: a cleaner, a driver, a junior colleague, a parent.","Find something they do better than you.","Tell them specifically, and ask how they learned to do it.","Use small courtesies all day: “Would you mind…”, “Thank you for…”."]'::jsonb, 'Who did you make feel important, and what did you ask them to teach you?', 0, false, '[]'::jsonb),
  ('0cf63e3a-f5f9-5b2f-aa36-0874ae4318cd', 10, 'Walk away from an argument', 'You cannot win an argument. If you lose it, you lose; if you win it, the other person feels smaller, resents the victory and keeps their opinion anyway. The only way to get the best of an argument is to avoid it. Demonstrating a point through what you do convinces people in a way that winning with words never will.', 'How to Win Friends and Influence People — Dale Carnegie (Part 3, Principle 1: avoid arguments) · The 48 Laws of Power — Robert Greene (Law 9)', '["Notice the first moment today when a disagreement starts heating up.","Stop. Take a breath before you answer.","Say: “You may be right. Let me think about that.”","Look for one thing in what they said that you can honestly agree with, and say it.","If it still matters tomorrow, raise it again calmly."]'::jsonb, 'What argument did you step away from, and what happened to it afterwards?', 0, false, '[]'::jsonb),
  ('0cf63e3a-f5f9-5b2f-aa36-0874ae4318cd', 11, 'Never say ''you''re wrong''', 'Telling someone they are wrong strikes at their intelligence, pride and self-respect; it makes them want to strike back, never to change their mind. You get further by admitting you might be mistaken yourself and suggesting you look at the facts together. People will drop almost any opinion they are allowed to drop on their own.', 'How to Win Friends and Influence People — Dale Carnegie (Part 3, Principle 2: show respect for the other person''s opinions)', '["Today, ban three phrases: “You''re wrong”, “No, actually…”, “That''s not true”.","When you disagree, start with: “I may be wrong — I often am. Can we look at it together?”","Ask a question instead of stating the correction.","Notice whether the other person softens."]'::jsonb, 'When did you want to say ''you''re wrong'', what did you say instead, and how did it land?', 0, false, '[]'::jsonb),
  ('0cf63e3a-f5f9-5b2f-aa36-0874ae4318cd', 12, 'Admit a mistake before anyone points it out', 'If you know you are going to be criticised anyway, it is far better to say it yourself first. Admitting a mistake quickly and fully takes the fight out of the other person and usually makes them generous in return. Defending yourself is what anyone can do; owning it sets you apart.', 'How to Win Friends and Influence People — Dale Carnegie (Part 3, Principle 3: if you are wrong, admit it quickly and emphatically)', '["Think of one thing you got wrong recently: something late, forgotten, mishandled or said badly.","Go to the person today and say it plainly: “I got this wrong. Here is what I should have done.”","No excuses and no “but”.","Say what you will do to put it right."]'::jsonb, 'What did you admit, and how did the other person respond?', 0, false, '[]'::jsonb),
  ('0cf63e3a-f5f9-5b2f-aa36-0874ae4318cd', 13, 'Begin in a friendly way', 'A drop of honey catches more flies than a gallon of gall. If someone''s heart is set against you, no amount of logic will reach them; friendliness is what opens the door. However tense the subject, the first minute decides the tone.', 'How to Win Friends and Influence People — Dale Carnegie (Part 3, Principle 4: begin in a friendly way)', '["Pick a conversation you expect to be tense: a complaint, a correction, a request.","Plan your first two sentences so that they are warm and sincere.","Open with something you appreciate or have in common before you raise the issue.","Keep your voice slower and lower than feels natural."]'::jsonb, 'What were your first two sentences, and how did the tense conversation go?', 0, false, '[]'::jsonb),
  ('0cf63e3a-f5f9-5b2f-aa36-0874ae4318cd', 14, 'Get a ''yes'' early', 'When someone has said no, their pride demands they stay consistent with it. So begin with what you both agree on, and keep stressing that you want the same end and differ only about the method. Each early yes moves the conversation in a direction that is easier to continue than to reverse.', 'How to Win Friends and Influence People — Dale Carnegie (Part 3, Principle 5: get the other person saying “yes, yes” immediately)', '["Before a discussion where you want agreement, write three things you both clearly agree on.","Open with those as questions the other person will answer yes to.","Only then raise the point you differ on.","If you hear a no, go back to common ground before continuing."]'::jsonb, 'What were your three points of agreement, and did starting with them change the outcome?', 0, false, '[]'::jsonb),
  ('0cf63e3a-f5f9-5b2f-aa36-0874ae4318cd', 15, 'Let the other person do the talking', 'Most people trying to win others over talk too much themselves. The other person knows more about their own problems and business than you do, so ask and let them tell you. Even our friends would rather tell us about their achievements than listen to ours.', 'How to Win Friends and Influence People — Dale Carnegie (Part 3, Principle 6: let the other person do a great deal of the talking)', '["In one conversation where you want something, aim to speak for less than a third of the time.","Ask questions that begin with “how” or “what”.","When you disagree, do not interrupt. Let them finish everything they have to say.","Resist telling your own success story today."]'::jsonb, 'How much of the conversation did you manage not to fill, and what did you learn by staying quiet?', 0, false, '[]'::jsonb),
  ('0cf63e3a-f5f9-5b2f-aa36-0874ae4318cd', 16, 'Let it be their idea', 'People have far more faith in ideas they discover for themselves than in ones handed to them. Making suggestions and letting the other person think out the conclusion works better than pushing your view. Whether you get the credit matters less than whether the thing gets done.', 'How to Win Friends and Influence People — Dale Carnegie (Part 3, Principle 7: let the other person feel that the idea is theirs)', '["Choose one idea you want someone to accept.","Do not present it. Ask for their thoughts on the problem instead.","Guide with questions: “What if we…?”, “What do you think would happen if…?”","When they arrive at something close to your idea, let them own it and say “I like your suggestion.”"]'::jsonb, 'What idea did you let someone else arrive at, and how did it feel not to take the credit?', 0, false, '[]'::jsonb),
  ('0cf63e3a-f5f9-5b2f-aa36-0874ae4318cd', 17, 'See it from their side', 'Other people may be completely wrong, but they do not think so. There is a reason they think and act as they do; find that reason and you have the key to their actions. Honestly asking “how would I feel in their place?” saves time and removes most of the irritation.', 'How to Win Friends and Influence People — Dale Carnegie (Part 3, Principle 8: try honestly to see things from the other person''s point of view)', '["Pick someone you disagree with or find difficult.","Write three sentences as if you were them, starting with “I…”. Describe their situation, pressures and wants.","Ask yourself: if I were in their place, would I act any differently?","Start your next conversation with them from that understanding."]'::jsonb, 'Whose side did you write from, and what did you understand that you had been missing?', 0, false, '[]'::jsonb),
  ('0cf63e3a-f5f9-5b2f-aa36-0874ae4318cd', 18, 'Say ''I don''t blame you for feeling that way''', 'Most people you meet are hungry for sympathy, and one sentence can stop an argument and create goodwill: “I don''t blame you at all for feeling as you do. In your place I would feel the same.” You can say it honestly, because with their history and their circumstances, you would.', 'How to Win Friends and Influence People — Dale Carnegie (Part 3, Principle 9: be sympathetic with the other person''s ideas and desires)', '["Listen today for someone who is upset, annoyed or complaining.","Before solving anything, say: “I don''t blame you for feeling that way. In your position I would feel the same.”","Then stay quiet and let them continue.","Only after they have finished, ask: “What would help?”"]'::jsonb, 'Who did you offer sympathy to, and what changed after you said it?', 0, false, '[]'::jsonb),
  ('0cf63e3a-f5f9-5b2f-aa36-0874ae4318cd', 19, 'Appeal to the better motive', 'People usually have two reasons for doing something: one that sounds good and the real one. They will think of the real one without your help, so appeal to the nobler one. Most people want to see themselves as honest and fair, and they respond to being treated as if they are.', 'How to Win Friends and Influence People — Dale Carnegie (Part 3, Principle 10: appeal to the nobler motives)', '["Think of a request you need to make where pressure would be the easy route.","Ask yourself which good quality the person likes to see in themselves: fairness, reliability, generosity, professionalism.","Frame the request around it: “I know you''re someone who keeps their word, so I wanted to ask you directly…”","Mean it. This only works if you genuinely believe it of them."]'::jsonb, 'What motive did you appeal to, and how did the person respond to being seen that way?', 0, false, '[]'::jsonb),
  ('0cf63e3a-f5f9-5b2f-aa36-0874ae4318cd', 20, 'Show it, don''t just say it', 'Merely stating a truth is not enough. It has to be made vivid, interesting and dramatic — shops, films and advertisers all know this. A demonstration people can see convinces them faster than any amount of explanation.', 'How to Win Friends and Influence People — Dale Carnegie (Part 3, Principle 11: dramatise your ideas)', '["Pick one point you need to get across today.","Find a way to show it instead of saying it: an object, a picture, a number made physical, a before-and-after, a short story.","Use it in the conversation or message.","Watch the difference in attention."]'::jsonb, 'What point did you dramatise, how did you show it, and how did people react?', 0, false, '[]'::jsonb),
  ('0cf63e3a-f5f9-5b2f-aa36-0874ae4318cd', 21, 'Throw down a friendly challenge', 'What truly motivates people is not money alone but the work itself and the chance to prove their worth. The desire to excel, to win at something, to feel capable, is a powerful spur. A challenge offered in good spirit gets more than an order ever does.', 'How to Win Friends and Influence People — Dale Carnegie (Part 3, Principle 12: throw down a challenge)', '["Find something that is going slowly: a task at home, a team goal, your own habit.","Turn it into a game with a visible score: a number on a board, a time to beat, a streak.","Offer it as a challenge, not a demand: “Think we can beat yesterday?”","Celebrate the result, whoever wins."]'::jsonb, 'What challenge did you set, and what did it do to people''s energy — or your own?', 0, false, '[]'::jsonb),
  ('0cf63e3a-f5f9-5b2f-aa36-0874ae4318cd', 22, 'Start with praise', 'It is always easier to hear unpleasant things after hearing some praise of your good points. Beginning with honest appreciation works like the dentist''s anaesthetic: the drilling still happens, but the pain is dulled. The praise must be true, or it will be heard as a trick.', 'How to Win Friends and Influence People — Dale Carnegie (Part 4, Principle 1: begin with praise and honest appreciation)', '["Think of someone whose work or behaviour you need to correct.","Write down two things they genuinely do well.","Open the conversation with those, specifically.","Then raise the one thing you would like changed."]'::jsonb, 'What did you praise first, and how did the person take the correction that followed?', 0, false, '[]'::jsonb),
  ('0cf63e3a-f5f9-5b2f-aa36-0874ae4318cd', 23, 'Swap ''but'' for ''and''', 'Many people begin criticism with sincere praise, then say ''but'' — and the listener immediately doubts the praise. Changing that one word to ''and'', and pointing to the mistake indirectly, lets the person correct it without feeling attacked. Indirect works wonders with people who resent direct criticism.', 'How to Win Friends and Influence People — Dale Carnegie (Part 4, Principle 2: call attention to people''s mistakes indirectly)', '["Catch yourself today whenever you say praise followed by “but”.","Replace it with “and”: “You did a great job on this, and if the last section is as clear as the first, it will be excellent.”","Or correct by example: quietly do the thing the right way where they can see it.","Notice how the person reacts compared with a direct correction."]'::jsonb, 'What ''but'' did you turn into an ''and'', and what was the reaction?', 0, false, '[]'::jsonb),
  ('0cf63e3a-f5f9-5b2f-aa36-0874ae4318cd', 24, 'Mention your own mistakes first', 'It is far easier to listen to a list of your faults if the person criticising begins by humbly admitting that they, too, are far from perfect. Talking about your own errors first lowers the other person''s guard and makes the conversation one between equals.', 'How to Win Friends and Influence People — Dale Carnegie (Part 4, Principle 3: talk about your own mistakes before criticising the other person)', '["Before giving any feedback today, recall a time you made the same or a similar mistake.","Start with it: “I did exactly this when I started, and it took me a while to learn…”","Then make your suggestion.","Keep your own story short and true."]'::jsonb, 'Which mistake of your own did you share, and how did it change the conversation?', 0, false, '[]'::jsonb),
  ('0cf63e3a-f5f9-5b2f-aa36-0874ae4318cd', 25, 'Ask instead of ordering', 'Nobody likes to take orders. Asking questions such as “You might consider this” or “Do you think that would work?” lets people correct their own errors, protects their pride and makes them want to cooperate. People are more likely to carry out a decision they helped to make.', 'How to Win Friends and Influence People — Dale Carnegie (Part 4, Principle 4: ask questions instead of giving direct orders)', '["Count how many direct orders you give today, at work and at home.","Turn each one into a question: “Could we…?”, “What do you think about…?”, “Is there a way to…?”","Wait for the answer and take it seriously.","Note which requests went more smoothly as questions."]'::jsonb, 'Which order did you turn into a question, and what did the other person come back with?', 0, false, '[]'::jsonb),
  ('0cf63e3a-f5f9-5b2f-aa36-0874ae4318cd', 26, 'Let them save face', 'Even when we are right and the other person is plainly wrong, we only destroy their ego by making them lose face. A few considerate words and a real understanding of their position do far more than a public victory. What matters is not what you think of someone, but what they think of themselves.', 'How to Win Friends and Influence People — Dale Carnegie (Part 4, Principle 5: let the other person save face)', '["Notice a moment today when someone is wrong in front of others.","Do not correct them publicly. Give them an exit: “That''s easy to mix up” or “I may not have explained it well.”","If it needs correcting, do it privately afterwards.","Never make someone admit fault in front of an audience."]'::jsonb, 'Whose dignity did you protect today, and what did you say to give them a way out?', 0, false, '[]'::jsonb),
  ('0cf63e3a-f5f9-5b2f-aa36-0874ae4318cd', 27, 'Praise every small improvement', 'Praise is like sunlight to the human spirit: we cannot grow without it, yet most of us are quick with the cold wind of criticism and slow with warmth. Abilities wither under blame and blossom under encouragement. Be specific, so the praise is believed.', 'How to Win Friends and Influence People — Dale Carnegie (Part 4, Principle 6: praise the slightest improvement and praise every improvement)', '["Choose one person who is learning or struggling with something.","Watch for any improvement, however slight.","Tell them exactly what was better: not “good job”, but “you explained that more clearly than last time.”","Do it three times today, with three different people if you can."]'::jsonb, 'What small improvement did you praise, and how specific were you?', 0, false, '[]'::jsonb),
  ('0cf63e3a-f5f9-5b2f-aa36-0874ae4318cd', 28, 'Give them a reputation to live up to', 'If you want someone to improve in a certain respect, act as though that trait were already one of their strengths. Give them a fine reputation to live up to, and they will make great efforts not to disappoint you. People rise to what is expected of them.', 'How to Win Friends and Influence People — Dale Carnegie (Part 4, Principle 7: give the other person a fine reputation to live up to)', '["Think of someone whose reliability, care or attitude has slipped.","Recall a time when they showed exactly the quality you want.","Tell them: “I''ve always thought of you as someone who [quality], which is why I wanted to give you this.”","Then trust them with it."]'::jsonb, 'What reputation did you give someone, and what did they do with it?', 0, false, '[]'::jsonb),
  ('0cf63e3a-f5f9-5b2f-aa36-0874ae4318cd', 29, 'Make the fault seem easy to fix', 'Tell someone they are stupid at something and have no gift for it, and you have destroyed almost every reason for them to try. Be liberal with encouragement, make the thing seem easy to do, and show your faith in their ability — they will practise until the dawn comes in the window.', 'How to Win Friends and Influence People — Dale Carnegie (Part 4, Principle 8: use encouragement; make the fault seem easy to correct)', '["Pick a mistake someone keeps making — or one of your own.","Break the fix into one small, obvious step.","Say: “This is an easy one to fix. You already have the hard part. Just try [small step].”","Follow up tomorrow and notice the effort."]'::jsonb, 'What fault did you make feel fixable, and what small step did you suggest?', 0, false, '[]'::jsonb),
  ('0cf63e3a-f5f9-5b2f-aa36-0874ae4318cd', 30, 'Make them glad to do it', 'A good leader makes the other person happy about doing the thing suggested. Be sincere, know exactly what you want, think about what the person really wants, and match the two when you ask. Giving people a role or a title they are proud of often does more than a reward.', 'How to Win Friends and Influence People — Dale Carnegie (Part 4, Principle 9: make the other person happy about doing the thing you suggest)', '["Choose a task you need someone else to do.","Write down what they would gain from doing it: skill, recognition, trust, a say in how it is done.","Make the request around that benefit, and give them ownership: “Would you take charge of this?”","Thank them for the result afterwards in front of others."]'::jsonb, 'What task did you hand over, and how did you make the other person glad to take it?', 0, false, '[]'::jsonb),
  ('0cf63e3a-f5f9-5b2f-aa36-0874ae4318cd', 31, 'Mirror their last three words', 'People fear what is different and are drawn to what is similar. Repeating the last one to three words someone has said — calmly, as a question — makes them feel heard and prompts them to explain further, without you having to argue or agree. It is the simplest way to keep someone talking and learn what they really want.', 'Never Split the Difference — Chris Voss (mirroring)', '["In three conversations today, repeat the last one to three words the other person said, with a gentle upward tone.","Example: “…it''s just been a difficult month.” — “A difficult month?”","Then stay silent for at least four seconds. Let them fill the gap.","Use a calm, slow voice. Do not overdo it; once or twice per conversation is enough."]'::jsonb, 'What did you mirror, and what extra information came out after the silence?', 0, false, '[]'::jsonb),
  ('0cf63e3a-f5f9-5b2f-aa36-0874ae4318cd', 32, 'Label the emotion', 'Naming what the other person is feeling takes the heat out of it. A label starts with “It seems like…”, “It sounds like…” or “It looks like…”, never with “I”. When someone feels understood, they stop defending and start talking — and that is where agreement becomes possible.', 'Never Split the Difference — Chris Voss (labeling and tactical empathy)', '["Listen today for someone who is frustrated, worried or hesitant.","Name it without judging: “It sounds like you''re worried this will fall on you” or “It seems like this has been frustrating.”","Pause after the label and let them respond. Do not explain it or soften it.","If you got it wrong, they will correct you — that helps too.","Before a hard request, label their likely objections first: “You''re probably thinking I''m asking for too much.”"]'::jsonb, 'Which emotion did you label, and how did the person respond once it was named?', 0, false, '[]'::jsonb),
  ('0cf63e3a-f5f9-5b2f-aa36-0874ae4318cd', 33, 'Ask ''how'' and ''what'' questions', 'Open questions that start with “how” or “what” give the other side the feeling of being in control while steering them to solve your problem. “How am I supposed to do that?” is a way of saying no without saying it, and it invites them to offer a better option. Avoid “why”, which sounds like an accusation.', 'Never Split the Difference — Chris Voss (calibrated questions)', '["Pick one negotiation, however small: a price, a deadline, a chore, a favour.","Prepare three questions: “What is the biggest challenge you face here?”, “How can we solve this together?”, “How am I supposed to do that?”","Ask them calmly and wait for the answer.","Do not use “why” or any question that can be answered with yes or no.","Look back over 33 days and choose the three principles you will keep using every day."]'::jsonb, 'What did you negotiate, which question worked best, and which three principles are you keeping?', 0, false, '[]'::jsonb),
  ('053903b3-3072-5e9d-a71a-662e772028d6', 1, 'Get Claude Pro, the desktop app — and chat vs Code', 'Everything in this workshop runs on Claude Code — the part of Claude that can work with files and run programs on your computer. It comes with a paid Claude plan; Pro is the cheapest one that includes it, and it''s the only thing you must pay for to follow along. Claude chat is for thinking and writing (ideas, hooks, captions). Claude Code is for doing: it opens a folder, installs tools, runs programs and creates files. A video is a file, so the videos are made in Code.', '', '["Go to claude.ai and sign up, or log in if you already have an account.","Upgrade to Claude Pro using the link below. Check the price for your country before you pay — it is billed by Anthropic, not by us.","Download the Claude desktop app for Windows or Mac (link below), install it and log in with the same account.","On Linux there is no desktop app yet: install Claude Code in the terminal with the command below, then run claude inside your studio folder. Every other lesson works the same.","Open the app. Use chat for brainstorming, hooks, captions and planning. Use Code for anything that should end up as a file — videos, voiceovers, images, folders.","Code asks permission before it runs commands on your computer. Read what it wants to do, then allow it.","Screens described as of November 2026 — if something has moved, the video for this lesson shows where."]'::jsonb, '', 0, true, '[{"kind":"link","label":"Upgrade to Claude Pro","content":"https://claude.ai/upgrade"},{"kind":"link","label":"Download the Claude desktop app","content":"https://claude.ai/download"},{"kind":"command","label":"Install Claude Code (Linux terminal)","os":"linux","content":"curl -fsSL https://claude.ai/install.sh | bash"},{"kind":"note","label":"Rule of thumb","content":"If the answer should be a file on your computer, use Code. Both use the same Pro plan; long video renders run on your own computer, so they don''t use up Claude messages while they render."}]'::jsonb),
  ('053903b3-3072-5e9d-a71a-662e772028d6', 2, 'Set up your studio folder and install everything with one prompt', 'You don''t need to know any video software. You make one folder, open it in Claude Code on your own computer (not the cloud — video files are big and your footage stays private), and paste one prompt. Claude installs the free tools that make video possible and checks they work.', '', '["Choose where your studio lives — Documents, Desktop, another drive, anywhere you like. Tip: avoid folders synced by OneDrive, iCloud or Dropbox if you can; big video files sync slowly.","Make a folder called Animation Studio there, with three folders inside: raw, references and exports. Create them by hand, or open a terminal in the place you chose and paste the command for your system below.","In the Claude desktop app, open Code, choose to work locally on your computer (not in the cloud) and select your Animation Studio folder.","Ask Claude: “What folders do you see here?” It should list raw, references and exports.","Paste the setup prompt below. Allow each install when Claude asks — some ask for your computer password, which is normal. It can take 10–20 minutes.","When it finishes, open exports and play test-hyperframes.mp4 and test-remotion.mp4. If you see “Studio ready”, it worked.","Paste the second prompt to save your studio rules. Claude reads that file every time you work in this folder.","If anything fails, copy the error into Claude and ask it to fix it. That works most of the time.","Screens described as of November 2026 — if something has moved, the video for this lesson shows where."]'::jsonb, '', 0, true, '[{"kind":"command","label":"Create the folders here (Windows PowerShell)","os":"windows","content":"mkdir \"Animation Studio\\raw\", \"Animation Studio\\references\", \"Animation Studio\\exports\""},{"kind":"command","label":"Create the folders here (Mac Terminal)","os":"mac","content":"mkdir -p \"Animation Studio/\"{raw,references,exports}"},{"kind":"command","label":"Create the folders here (Linux terminal)","os":"linux","content":"mkdir -p \"Animation Studio/\"{raw,references,exports}"},{"kind":"note","label":"Opening a terminal in the right place","content":"Windows: open the folder in File Explorer, right-click an empty space and choose “Open in Terminal”. Mac: right-click the folder in Finder → Services → “New Terminal at Folder”. Linux: right-click in the folder → “Open in Terminal”. Or type cd followed by the folder''s path."},{"kind":"note","label":"What each folder is for","content":"raw = your own footage (you talking, screen recordings). references = videos whose style you like, for study only. exports = finished videos."},{"kind":"prompt","label":"Setup prompt — install everything","content":"Set up this folder as my AI video studio. Work out which operating system I''m on and use its normal installer (winget on Windows, Homebrew on Mac, apt on Linux). Ask before anything that needs admin rights.\n\n1. Check for these and install any that are missing:\n   - FFmpeg (full build)\n   - Node.js (LTS) with npm\n   - Python 3.12 with pip\n\n2. Install the video frameworks globally with npm:\n   - HyperFrames CLI (\"hyperframes\"): HTML + GSAP scenes rendered to MP4, with check, snapshot and transcribe commands\n   - Remotion CLI (\"@remotion/cli\"): React-based video rendering\n\n3. Install these Python packages with pip:\n   - openai-whisper (with torch): free local captions and word timings\n   - kokoro-onnx and onnxruntime: free local text-to-speech, as a backup to ElevenLabs\n   - soundfile and numpy: audio processing helpers\n   - requests: for calling the ElevenLabs voiceover API\n\n4. Create two starter projects for animated vertical videos (1080x1920, 30 fps):\n   - \"studio-hyperframes\": a HyperFrames project (npx hyperframes init), with the CLI version pinned in package.json\n   - \"studio-remotion\": a Remotion project with a 1080x1920, 30 fps composition\n\n5. Render a 5-second test video that says \"Studio ready\" from each project:\n   - exports/test-hyperframes.mp4\n   - exports/test-remotion.mp4\n   Then run \"npx hyperframes transcribe\" on one of them to confirm captions work.\n\n6. Finish with a short list of what was installed, what was already there, and anything that failed with the fix."},{"kind":"prompt","label":"Save your studio rules","content":"Create a file called CLAUDE.md in this folder with exactly this content, then confirm:\n\n# Studio rules (Claude reads this file every time)\n\n## Tools\n- Animated videos: the studio-hyperframes (HTML + GSAP) or studio-remotion (React) project — pick whichever suits the style.\n- Captions and word timings: npx hyperframes transcribe, or openai-whisper.\n- Free backup voice: kokoro-onnx (only if I ask, or ElevenLabs isn''t set up).\n\n## Folders\n- raw/ — my own footage (UGC, screen recordings). Edit it freely.\n- references/ — videos I like, for studying style ONLY. Never reuse, re-upload or copy them into a video.\n- exports/ — finished videos and audio. Name files: YYYY-MM-DD-short-title.mp4\n\n## Video defaults\n- Vertical 1080x1920, 30 fps, MP4 (H.264) with AAC audio.\n- Burned-in captions, large and readable.\n- Keep text out of the top 250 px and bottom 420 px (Instagram covers those areas).\n- Strong hook in the first 2 seconds.\n\n## Sound\n- ElevenLabs is for VOICEOVER ONLY. Read the key from the ELEVENLABS_API_KEY environment variable. Never print, log or save the key.\n- Music and sound effects: free, royalty-free sources only (for example YouTube Audio Library, Pixabay Music, Freesound CC0). Write every source and its licence in credits.md.\n- Before calling ElevenLabs, tell me roughly how many characters it will use.\n\n## Working style\n- Show me the script and scene plan before rendering anything long.\n- After rendering, tell me the file name and length."},{"kind":"note","label":"Licences","content":"FFmpeg, Node.js, Python, Whisper and Kokoro are free. Remotion is free for individuals and small teams — check remotion.dev/license if you work for a company. Check each tool''s licence before commercial use."}]'::jsonb),
  ('053903b3-3072-5e9d-a71a-662e772028d6', 3, 'Connect ElevenLabs for voiceovers', 'Great voiceovers make AI videos feel finished. ElevenLabs has a free plan, but the voices are more limited and the free plan has usage limits and may not allow commercial use — check their current terms. For better sound, the Starter plan costs about US$5 a month (paid to ElevenLabs). If you''d rather not pay, your studio already has a free backup voice (Kokoro), with lower quality.', '', '["Sign up at elevenlabs.io (link below).","Open your profile or the Developers area and find API Keys. Create a new key and copy it.","Set the key on your computer with the command for your system below. Replace paste-your-key-here with your key, and keep the quotes.","Fully quit the Claude desktop app (not just the window) and open it again, so it picks up the new key.","Paste the check prompt below into Claude Code. It should answer “yes” without showing the key.","Never paste your key into a chat or a prompt. If it ever leaks, delete it in ElevenLabs and create a new one."]'::jsonb, '', 0, false, '[{"kind":"link","label":"ElevenLabs","content":"https://elevenlabs.io"},{"kind":"command","label":"Save the key (Windows PowerShell)","os":"windows","content":"[Environment]::SetEnvironmentVariable(''ELEVENLABS_API_KEY'', ''paste-your-key-here'', ''User'')"},{"kind":"command","label":"Save the key (Mac Terminal)","os":"mac","content":"echo ''export ELEVENLABS_API_KEY=\"paste-your-key-here\"'' >> ~/.zshrc\nlaunchctl setenv ELEVENLABS_API_KEY \"paste-your-key-here\""},{"kind":"command","label":"Save the key (Linux terminal)","os":"linux","content":"echo ''export ELEVENLABS_API_KEY=\"paste-your-key-here\"'' >> ~/.bashrc\nsource ~/.bashrc"},{"kind":"prompt","label":"Check the key is set","content":"Check whether the environment variable ELEVENLABS_API_KEY is set. Do not print its value — just answer yes or no. If it''s missing, tell me how to fix it for my operating system."},{"kind":"note","label":"Mac only","content":"The launchctl line makes the key visible to the desktop app until you restart your Mac. After a restart, run that one line again (or launch Claude Code from Terminal, which reads ~/.zshrc)."}]'::jsonb),
  ('053903b3-3072-5e9d-a71a-662e772028d6', 4, 'References and your first animated video', 'Good creators steal like artists: they collect what they admire, study why it works, and mix it into something of their own. Your references folder is that collection — you never reuse the clips, you learn their style. Then you make your first video: one idea, a strong hook, 20–30 seconds. Claude writes the script, builds the animation and renders the file. You direct.', 'Steal Like an Artist — Austin Kleon', '["Find 3–5 short videos whose animation style you love. Save them into references (only where the app allows it, or screen-record them for private study). Never post them, or a copy of them, as your own.","Paste the style-guide prompt. Claude pulls frames from each reference and writes style notes you''ll reuse for every video.","Pick one idea you could explain in 30 seconds — for example three lessons from a book or one surprising fact.","Paste the first-video prompt and replace the part in brackets with your idea.","Read the script Claude shows you. Change anything that doesn''t sound like you, then say “go ahead and render”.","Watch it on your phone. Ask for changes in plain words: “make scene 2 faster”, “bigger text”, “the hook needs to hit harder”. Three or four small rounds is normal."]'::jsonb, '', 0, false, '[{"kind":"prompt","label":"Turn your references into a style guide","content":"Study the videos in references/. For each one, use ffmpeg to extract one frame per second into references/frames/<video-name>/, then look at the frames.\n\nWrite references/style-notes.md with, for each video:\n- colours (hex codes), fonts or lettering style, backgrounds\n- how things move and how scenes change (cuts, zooms, slides)\n- pacing: roughly how many seconds per scene\n- how text appears on screen\n- what happens in the first 2 seconds (the hook)\n\nEnd with a short \"what these have in common\" section."},{"kind":"prompt","label":"Your first video","content":"Make a 20–30 second vertical Instagram Reel about: [YOUR IDEA — e.g. \"3 money habits from The Psychology of Money\"].\n\nStyle: inspired by references/style-notes.md — borrow the feel, not the exact design.\nStructure:\n- Hook in the first 2 seconds as big on-screen text.\n- 3–5 scenes, one idea per scene.\n- Last scene: \"Follow for more\".\n\nFirst show me: the on-screen text for each scene, a voiceover script, and how long each scene lasts. Wait for my OK.\nThen build it in studio-hyperframes (or studio-remotion if that suits the style better) and render to exports/ following CLAUDE.md."}]'::jsonb),
  ('053903b3-3072-5e9d-a71a-662e772028d6', 5, 'Edit your own footage (UGC)', 'If you film yourself, Claude can do the boring parts of editing: cut the pauses and mistakes, pick the best takes, move your strongest line to the start, add captions and punch-in zooms. You don''t open an editor.', '', '["Put your clips in raw. Phone videos are perfect — film vertically.","Paste the prompt below.","Check the result. If a cut feels wrong, tell Claude the timestamp: “at 0:12 you cut my sentence short”.","Ask for a second version with a different hook and keep the one you prefer."]'::jsonb, '', 0, false, '[{"kind":"prompt","label":"Edit raw footage into a reel","content":"Edit the clips in raw/ into a 30–45 second vertical reel.\n\n- Transcribe them (npx hyperframes transcribe or whisper), then remove silences, \"um\"s and repeated takes. Keep the clearest version of each point.\n- Start with the strongest sentence as the hook, even if it was said later.\n- Add burned-in captions, 2–4 words at a time, with the current word highlighted.\n- Add a subtle zoom-in every 4–6 seconds to keep it moving.\n- Even out the audio volume.\nRender to exports/ following CLAUDE.md and tell me the length."}]'::jsonb),
  ('053903b3-3072-5e9d-a71a-662e772028d6', 6, 'Voiceover, free sound and the export checklist', 'Sound is half of a video. ElevenLabs gives you a natural voice; free music and sound effects do the rest. Your studio rules keep ElevenLabs for the voice only, so you don''t spend credits on sounds you can get for free. Then a 30-second checklist catches the mistakes that cost you views.', '', '["Paste the voiceover prompt and pick one of the voices Claude suggests.","Listen to the voiceover on its own before it goes into the video. Ask for a slower pace or a different voice if needed.","Paste the music prompt to add quiet background music and a few sound effects from free sources.","Check credits.md — every music and sound file should be listed with its source and licence.","No ElevenLabs plan? Ask Claude to use the free Kokoro voice instead. It works, but sounds less natural.","Before posting anything, run the export checklist below."]'::jsonb, '', 0, false, '[{"kind":"prompt","label":"Voiceover with ElevenLabs","content":"Create the voiceover for my latest video using the ElevenLabs API. Read the key from the ELEVENLABS_API_KEY environment variable and never print it.\n\n- First tell me roughly how many characters this will use.\n- Suggest 3 natural-sounding voices that fit the video and wait for me to choose.\n- Save the audio to exports/audio/, then add it to the video and re-render.\nElevenLabs is for the voiceover only."},{"kind":"prompt","label":"Free music and sound effects","content":"Add background music and 2–4 sound effects to my latest video. Use only free, royalty-free sources (for example YouTube Audio Library, Pixabay Music, Freesound CC0). Do not use ElevenLabs for these.\n\n- Keep the music clearly quieter than the voice.\n- Add sounds only where something happens on screen (a pop for text, a whoosh for a transition).\n- List every file with its source and licence in credits.md, then re-render."},{"kind":"note","label":"Export checklist","content":"1080x1920 · 30 fps · MP4 · captions on · hook in the first 2 seconds · no text in the top 250 px or bottom 420 px · sound checked on a phone · credits.md updated · a clear cover frame."}]'::jsonb),
  ('053903b3-3072-5e9d-a71a-662e772028d6', 7, 'Invent new styles', 'Audiences get bored of a look surprisingly fast — what stopped the scroll last month is wallpaper today. When you start seeing a style everywhere, it''s about to stop working. The fix is to keep inventing: combine two styles that don''t usually meet, add one unexpected twist, and test small before you commit.', 'Steal Like an Artist — Austin Kleon', '["Paste the style prompt. Claude invents five new styles from your references.","Pick the two you like and let Claude make a 10-second test of each.","Use the winner for your next three videos, then invent again."]'::jsonb, '', 0, false, '[{"kind":"prompt","label":"Invent five new styles","content":"Read references/style-notes.md. Invent 5 new animation styles that each combine two different references with one unexpected element (for example paper-cut + neon, chalkboard + 3D type, newspaper collage + glitch).\n\nFor each style give: a name, colours (hex), fonts, how things move, and why it would stop someone scrolling.\nThen make a 10-second test video of the two strongest styles in exports/style-tests/."}]'::jsonb),
  ('053903b3-3072-5e9d-a71a-662e772028d6', 8, 'Grow on Instagram: trends, 3 a day and your weekly routine', 'You can make videos now — this is how they grow an account. Spot what''s working in your niche, post three a day as a system rather than a scramble, and review your numbers once a week. Results take weeks, not days, and they vary from account to account, but a steady routine is what moves the numbers.', 'Contagious — Jonah Berger · Show Your Work! — Austin Kleon', '["Spot trends: spend 15 minutes a day in Reels and Explore for your niche. Save every reel that stops your thumb and note why — the hook, the style, the length, the audio. Turn your notes into ideas with the trends prompt.","Watch for fatigue: when you see the same style everywhere, it''s about to stop working. That''s your signal to invent a new one.","Post 3 videos a day at 9 am, 2 pm and 8 pm, in your main audience''s timezone. This is the schedule that grew @mindfrombooks — test it and adjust for your audience.","Make videos in batches (6–9 in one sitting) and schedule them with Instagram''s built-in scheduling or Meta Business Suite, so posting never depends on remembering.","Every post: a hook in the first 2 seconds, captions on, one idea, a clear cover. Caption: the first line repeats the hook, then 1–3 short lines and 3–5 relevant hashtags.","Reply to comments in the first hour after posting — it shows people the account is alive.","Once a week, check each reel''s views, watch time, shares, saves and follows. Shares and saves matter most. Paste the numbers into the weekly review prompt and test one change the next week.","Your week: Sunday — trend notes and plan 21 posts. Two sittings — make and schedule. Every day — reply to comments. Saturday — weekly review and one new style.","Stuck on a step, or something on your computer won''t work? Send a message to @mindfrombooks on Instagram."]'::jsonb, '', 0, false, '[{"kind":"prompt","label":"Turn trends into ideas","content":"Here are notes on reels that stopped me today in my niche ([YOUR NICHE]):\n[PASTE NOTES]\n\nFind the patterns: hooks, formats, lengths and styles that repeat. Then give me 10 video ideas that use those patterns in my own way, each with a 1-line hook. Mark the 3 you think are strongest and why."},{"kind":"prompt","label":"Plan a week of posts","content":"Plan 21 Instagram Reels for next week (3 a day, at 9 am, 2 pm and 8 pm) for my niche: [YOUR NICHE].\nFor each: the hook (on-screen, under 8 words), the idea in one sentence, which style from references/style-notes.md to use, and a caption with 3–5 hashtags.\nMix formats so no two posts in a row look the same. Put it in a table I can copy."},{"kind":"prompt","label":"Weekly review","content":"Here are my Reels stats for the last 7 days:\n[PASTE: title, views, average watch time, shares, saves, follows]\n\n1. Which 3 did best and what do they have in common?\n2. Which 3 did worst and why might that be?\n3. Give me ONE change to test on every post next week, and 5 ideas that use what worked."},{"kind":"link","label":"Message @mindfrombooks on Instagram","content":"https://www.instagram.com/mindfrombooks/"}]'::jsonb)
